/** All translations for zizhitongjian ch.010 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "__FORCETOC__", literal: "—", idiomatic: "—" },
  { zh: "起強圉作噩，盡著雍閹茂，凡二年。", literal: "From Qiangyu Zuo'e through Zhu Yongyan Mao; two years in all.", idiomatic: "From Qiangyu Zuo'e through Zhu Yongyan Mao—two years in all." },
  { zh: "1冬，十月，韓信、張耳以兵數萬東擊趙。", literal: "1. In winter, the tenth month, Han Xin and Zhang Er led several tens of thousands of troops east to attack Zhao.", idiomatic: "1. In the tenth month of winter Han Xin and Zhang Er led tens of thousands east against Zhao." },
  { zh: "趙王及成安君陳餘聞之，聚兵井陘口，號二十萬。", literal: "The king of Zhao and Lord Cheng'an Chen Yu heard of it, gathered troops at Jingxing Pass, and claimed two hundred thousand.", idiomatic: "The king of Zhao and Lord Cheng'an Chen Yu heard of it, massed their forces at Jingxing Pass, and claimed two hundred thousand men." },
  { zh: "廣武君李左車說成安君曰：「韓信、張耳乘勝而去國遠鬥，其鋒不可當。", literal: "Lord Guangwu Li Zuoche urged Lord Cheng'an, saying: \"Han Xin and Zhang Er ride victory to fight far from their states; their edge cannot be withstood.", idiomatic: "Lord Guangwu Li Zuoche urged Lord Cheng'an: \"Han Xin and Zhang Er ride victory into a fight far from home; their edge cannot be turned.\"" },
  { zh: "臣聞『千里饋糧，士有饑色；", literal: "Your servant has heard: 'To supply grain from a thousand li, the soldiers show hunger;", idiomatic: "I have heard it said: 'Supply grain from a thousand li away, and your soldiers go hungry;" },
  { zh: "樵蘇後爨，師不宿飽。", literal: "when firewood and kindling come late to the cook-fires, the army does not sleep full.'", idiomatic: "when firewood and kindling lag behind the cook-fires, the army never sleeps on a full belly.'\"" },
  { zh: "』今井陘之道，車不得方軌，騎不得成列；", literal: "' Now the road through Jingxing: chariots cannot run abreast, horsemen cannot form ranks;", idiomatic: "' The road through Jingxing is so narrow that chariots cannot run abreast and horsemen cannot ride in formation;" },
  { zh: "行數百里，其勢糧食必在其後。", literal: "marching several hundred li, it is certain their grain and provisions trail behind.", idiomatic: "march several hundred li, and their grain and provisions must trail far behind." },
  { zh: "願足下假臣奇兵三萬人，從間路絕其輜重；", literal: "I beg you, my lord, to lend your servant thirty thousand picked troops to cut off their baggage train by a bypath;", idiomatic: "Lend me thirty thousand picked troops to cut their baggage train by a bypath;" },
  { zh: "足下深溝高壘勿與戰。", literal: "you, my lord, dig deep trenches and raise high ramparts and do not give battle.", idiomatic: "while you dig deep trenches, raise high ramparts, and refuse battle." },
  { zh: "彼前不得鬥，退不得還，野無所掠，不至十日，而兩將之頭可致於麾下；", literal: "They cannot fight ahead, cannot return behind, and have nothing to plunder in the wilds; within ten days the heads of both generals may be brought to your tent;", idiomatic: "They cannot fight ahead, cannot retreat, and will find nothing to plunder in the wild—within ten days both generals' heads may be laid at your feet;" },
  { zh: "否則必為二子所擒矣。", literal: "otherwise you will surely be taken by those two.", idiomatic: "otherwise you will surely be taken by those two.\"" },
  { zh: "」成安君嘗自稱義兵，不用詐謀奇計，曰：「韓信兵少而疲，如此避而不擊，則諸侯謂吾怯而輕來伐我矣。", literal: "\" Lord Cheng'an had styled himself leader of a righteous army and would not use deceit or stratagems. He said: \"Han Xin's troops are few and weary; if we avoid them and do not strike, the feudal lords will call us cowards and come lightly to attack us.", idiomatic: "\" Lord Cheng'an had called his army a force of righteousness and would hear no deceit or stratagem. He said: \"Han Xin's men are few and spent. If we shrink from them and refuse battle, every lord will call us cowards and come against us lightly." },
  { zh: "韓信使人間視，知其不用廣武君策，則大喜，乃敢引兵遂下。", literal: "Han Xin sent men to spy and learned that he would not use Lord Guangwu's plan; he was greatly pleased and then dared lead his army straight down.", idiomatic: "Han Xin sent spies and learned that Lord Guangwu's plan was rejected. He rejoiced, then dared lead his army straight down." },
  { zh: "未至井陘口三十里，止舍。", literal: "Thirty li short of Jingxing Pass he halted and encamped.", idiomatic: "Thirty li short of Jingxing Pass he halted and made camp." },
  { zh: "夜半，傳發，選輕騎二千人，人持一赤幟，從間道萆山而望趙軍。", literal: "At midnight he issued orders to march; he chose two thousand light horsemen, each bearing one red banner, and by a hidden path over Mount Bi looked down on the Zhao army.", idiomatic: "At midnight he issued the order to march, chose two thousand light horsemen—each with a red banner—and by a hidden path over Mount Bi looked down on the Zhao army." },
  { zh: "誡曰：「趙見我走，必空壁逐我；", literal: "He charged them: \"When Zhao sees us flee, they will surely empty their walls to pursue us;", idiomatic: "He charged them: \"When Zhao sees us flee, they will empty their walls to pursue us;" },
  { zh: "若疾入趙壁，拔趙幟，立漢赤幟。", literal: "if you hurry into the Zhao camp, pull down the Zhao banners, and raise the Han red banners.", idiomatic: "when they do, rush into the Zhao camp, pull down their banners, and raise the Han red banners.\"" },
  { zh: "」令其裨將傳餐，曰：「今日破趙會食。", literal: "\" He ordered his lieutenant generals to pass out rations, saying: \"Today we break Zhao and dine together.", idiomatic: "\" He told his lieutenant generals to pass out rations: \"Today we break Zhao and dine together.\"" },
  { zh: "」諸將皆莫信，佯應曰：「諾。", literal: "\" The generals all disbelieved him and pretended to answer: \"Yes.", idiomatic: "\" The generals did not believe him and pretended to answer: \"Yes.\"" },
  { zh: "」信曰：「趙已先據便地為壁；", literal: "\" Xin said: \"Zhao has already seized favorable ground for its camp;", idiomatic: "\" Xin said: \"Zhao has already seized favorable ground for its camp;" },
  { zh: "且彼未見吾大將旗鼓，未肯擊前行，恐吾至阻險而還也。", literal: "moreover they have not yet seen our great general's flags and drums and will not strike the vanguard, fearing we may reach difficult ground and turn back.", idiomatic: "and they have not yet seen our command banners and drums—they will not strike the vanguard, fearing we may reach difficult ground and turn back.\"" },
  { zh: "」乃使萬人先行，出，背水陳。", literal: "\" He then sent ten thousand men ahead; they went out and formed their battle line with their backs to the water.", idiomatic: "\" He sent ten thousand men ahead. They went out and formed with their backs to the water." },
  { zh: "趙軍望見而大笑。", literal: "The Zhao army saw them and laughed aloud.", idiomatic: "The Zhao army saw them and laughed aloud." },
  { zh: "平旦，信建大將旗鼓，鼓行出井陘口；", literal: "At daybreak Xin raised the great general's flags and drums and advanced with drums beating out of Jingxing Pass;", idiomatic: "At daybreak Xin raised his command flags and drums and advanced with drums beating out of Jingxing Pass;" },
  { zh: "趙開壁擊之，大戰良久。", literal: "Zhao opened its walls and struck them; the great battle lasted long.", idiomatic: "Zhao opened its walls and struck; the battle raged long." },
  { zh: "於是信與張耳佯棄鼓旗，走水上軍；", literal: "Thereupon Xin and Zhang Er feigned abandonment of drums and banners and fled to the army on the water;", idiomatic: "Then Xin and Zhang Er feigned flight, casting aside drums and banners, and ran to the army on the water;" },
  { zh: "水上軍開入之，復疾戰。", literal: "the army on the water opened and admitted them, and they fought fiercely again.", idiomatic: "the army on the water opened ranks to admit them, and they fought again with fury." },
  { zh: "趙果空壁爭漢旗、鼓，逐信、耳。", literal: "Zhao indeed emptied its walls to seize the Han flags and drums and pursued Xin and Er.", idiomatic: "Zhao emptied its walls to seize Han flags and drums and pursued Xin and Er." },
  { zh: "信、耳已入水上軍，軍皆殊死戰，不可敗。", literal: "Xin and Er had already entered the army on the water; every soldier fought to the death and could not be broken.", idiomatic: "Xin and Er were already among the army on the water; every man fought as if death were certain, and none could be broken." },
  { zh: "信所出奇兵二千騎共候趙空壁逐利，則馳入趙壁，皆拔趙旗，立漢赤幟二千。", literal: "The two thousand horsemen Xin had sent out in surprise, watching together until Zhao emptied its walls to pursue gain, then galloped into the Zhao camp, pulled down every Zhao banner, and raised two thousand Han red banners.", idiomatic: "The two thousand horsemen Xin had sent in surprise watched until Zhao emptied its walls in pursuit, then galloped into the camp, pulled down every Zhao banner, and raised two thousand Han red banners." },
  { zh: "趙軍已不能得信等，欲還歸壁；", literal: "The Zhao army could no longer catch Xin and the rest and wished to return to camp;", idiomatic: "The Zhao army could no longer catch Xin and the rest and turned to return to camp;" },
  { zh: "壁皆漢赤幟，見而大驚，以為漢皆已得趙王將矣，兵遂亂，遁走，趙將雖斬之，不能禁也。", literal: "the walls were all Han red banners; seeing them they were greatly alarmed, thinking Han had already taken the king of Zhao and his generals; the troops then fell into disorder and fled. Though Zhao generals cut them down, they could not be stopped.", idiomatic: "but the walls were all Han red banners. They were stricken with alarm, thinking Han had already taken their king and generals. The army broke and fled; though Zhao officers cut men down, none could be stopped." },
  { zh: "於是漢兵夾擊，大破趙軍，斬成安君泜水上，禽趙王歇。", literal: "Thereupon Han troops struck from both sides, routed the Zhao army utterly, beheaded Lord Cheng'an on the waters of the Zhi, and captured King Xie of Zhao.", idiomatic: "Han troops struck from both sides and routed the Zhao army. Lord Cheng'an was beheaded on the Zhi; King Xie of Zhao was captured." },
  { zh: "諸將效首虜，畢賀，因問信曰：「兵法：『右倍山陵，前左水澤。", literal: "The generals presented heads and captives, all congratulated him, and then asked Xin: \"In the art of war: 'Have mountains and hills at your right, water and marsh at your front and left.", idiomatic: "The generals presented heads and captives and congratulated him, then asked: \"The art of war says: 'Mountains and hills at your right, water and marsh before and to your left." },
  { zh: "』今者將軍令臣等反背水陳，曰『破趙會食』，臣等不服，然竟以勝，此何術也？", literal: "' Yet today the general ordered us to form with our backs to the water contrary to this, saying 'Break Zhao and we dine together'—we were not convinced, yet in the end we won. What art is this?", idiomatic: "' Yet today you ordered us to form with our backs to the water and said 'Break Zhao and we dine together.' We were not convinced, yet we won. What art is this?\"" },
  { zh: "」信曰：「此在兵法，顧諸君不察耳。", literal: "\" Xin said: \"This too is in the art of war—only you gentlemen did not discern it.", idiomatic: "\" Xin said: \"This too is in the art of war—you simply did not see it.\"" },
  { zh: "兵法不曰『陷之死地而後生，置之亡地而後存』？", literal: "Does the art of war not say 'Cast them into deadly ground and they will live; set them in lost ground and they will survive'?", idiomatic: "Does the art of war not say 'Cast men into deadly ground and they live; set them in lost ground and they survive'?\"" },
  { zh: "且信非得素拊循士大夫也，此所謂『驅市人而戰之』，其勢非置之死地，使人人自為戰。", literal: "Moreover, Xin has not long comforted and led these officers and men—this is what is called 'driving market folk into battle.' The situation required placing them in deadly ground so that every man would fight for himself.", idiomatic: "And I have not long led these officers and men with my own hand—this is what men call 'driving market folk into battle.' I had to place them where death was certain, so every man would fight for himself." },
  { zh: "今予之生地，皆走，寧尚可得而用之乎？", literal: "If I now gave them ground where they could live, they would all flee—how could I still use them?", idiomatic: "Give them ground where they could live, and they would all flee—how then could I use them?\"" },
  { zh: "」諸將皆服，曰：「善！", literal: "\" The generals were all convinced and said: \"Excellent!", idiomatic: "The generals were convinced. \"Excellent!\" they said." },
  { zh: "非臣所及也。", literal: "Not what your servants could have reached.", idiomatic: "Beyond what we could have done.\"" },
  { zh: "信募生得廣武君者予千金。", literal: "Xin offered a thousand gold to whoever captured Lord Guangwu alive.", idiomatic: "Xin offered a thousand in gold to whoever brought Lord Guangwu in alive." },
  { zh: "有縛致麾下者，信解其縛，東鄉坐，師事之。", literal: "Someone bound and brought him to headquarters; Xin loosed his bonds, seated him facing east, and treated him as his teacher.", idiomatic: "Someone bound him and brought him in. Xin loosed his bonds, seated him facing east, and treated him as his teacher." },
  { zh: "問曰：「僕欲北攻燕，東代齊，何若而有功？", literal: "He asked: \"Your servant wishes to attack Yan in the north and supplant Qi in the east—how may he achieve merit?", idiomatic: "He asked: \"I mean to attack Yan in the north and supplant Qi in the east—how may I win merit?\"" },
  { zh: "」廣武君辭謝曰：「臣敗亡之虜，何足以權大事乎？", literal: "\" Lord Guangwu declined, saying: \"Your servant is a captive of a defeated and ruined army—how is he fit to weigh great affairs?", idiomatic: "\" Lord Guangwu declined: \"I am a captive from a ruined army—how am I fit to weigh great affairs?\"" },
  { zh: "」信曰：「僕聞之，百里奚居虞而虞亡，在秦而秦霸；", literal: "\" Xin said: \"Your servant has heard that Baili Xi dwelt in Yu and Yu perished; he dwelt in Qin and Qin became hegemon;", idiomatic: "\" Xin said: \"I have heard that Baili Xi dwelt in Yu and Yu perished, dwelt in Qin and Qin became hegemon;" },
  { zh: "非愚於虞而智於秦也，用與不用，聽與不聽也。", literal: "it was not that he was foolish in Yu and wise in Qin—it was use and disuse, heed and heedlessness.", idiomatic: "not that he was foolish in Yu and wise in Qin, but whether he was used and whether he was heard." },
  { zh: "誠令成安君聽足下計，若信者亦已為禽矣。", literal: "Had Lord Cheng'an truly heeded your plan, one such as Xin would already have been captured.", idiomatic: "Had Lord Cheng'an heeded your plan, I would already be a captive." },
  { zh: "以不用足下，故信得侍耳。", literal: "Because he did not use you, Xin was able to attend upon you.", idiomatic: "Because he did not use you, I am able to attend upon you now." },
  { zh: "今僕委心歸計，願足下勿辭。", literal: "Now your servant lays his heart bare and seeks your counsel—may you not decline.", idiomatic: "I lay my heart bare and seek your counsel—do not decline.\"" },
  { zh: "」廣武君曰：「今將軍涉西河，虜魏王，禽夏說；", literal: "\" Lord Guangwu said: \"Now the general has crossed the Western River, captured the king of Wei, and taken Xia Yue;", idiomatic: "\" Lord Guangwu said: \"You have crossed the Western River, captured the king of Wei, and taken Xia Yue;" },
  { zh: "東下井陘，不終朝而破趙二十萬眾，誅成安君；", literal: "marched east down through Jingxing, and before the morning was out broke Zhao's two hundred thousand; executed Lord Cheng'an;", idiomatic: "marched east through Jingxing and before noon broke Zhao's two hundred thousand and executed Lord Cheng'an;" },
  { zh: "名聞海內，威震天下，農夫莫不輟耕釋耒，衣俞衣甘食，傾耳以待命者，此將軍之所長也。", literal: "your name is heard within the seas, your might shakes all under Heaven—no farmer fails to stop plowing and lay down his hoe, dress in fine clothes and eat sweet food, and incline his ear awaiting your command. This is where the general excels.", idiomatic: "your name rings across the seas, your might shakes the realm—farmers lay down hoe and plow, dress in their best, eat sweet food, and listen for your command. This is your strength." },
  { zh: "然而眾勞卒罷，其實難用。", literal: "Yet the masses are weary and the soldiers spent—in truth they are hard to use.", idiomatic: "Yet your men are weary and spent—in truth they are hard to use." },
  { zh: "今將軍欲舉倦敝之兵，頓之燕堅城之下，欲戰不得，攻之不拔，情見勢屈；", literal: "Now the general wishes to raise worn and exhausted troops and halt them beneath Yan's stout walls—wishing to fight yet unable, wishing to storm yet unable to take; your intent is exposed and your strength bent;", idiomatic: "Now you mean to drive worn troops against Yan's stout walls—unable to fight, unable to storm; your intent is exposed and your strength bent;" },
  { zh: "曠日持久，糧食單竭。", literal: "days and months drag on, and grain and provisions run dry.", idiomatic: "days stretch on, and grain runs dry." },
  { zh: "燕既不服，齊必距境以自強。", literal: "If Yan does not submit, Qi will surely hold its borders to strengthen itself.", idiomatic: "If Yan does not submit, Qi will hold its borders and grow strong." },
  { zh: "燕、齊相持而不下，則劉、項之權未有所分也，此將軍所短也。", literal: "If Yan and Qi hold each other and are not brought down, then the power between Liu and Xiang will not yet be divided—this is where the general falls short.", idiomatic: "If Yan and Qi hold out and are not brought down, Liu and Xiang's contest will not yet be decided—this is your weakness." },
  { zh: "善用兵者，不以短擊長而以長擊短。", literal: "One who uses troops well does not strike with weakness against strength but with strength against weakness.", idiomatic: "A master of war strikes with strength against weakness, not weakness against strength." },
  { zh: "」韓信曰：「然則何由？", literal: "\" Han Xin said: \"Then by what means?", idiomatic: "\" Han Xin said: \"Then by what means?\"" },
  { zh: "」廣武君對曰：「方今為將軍計，莫如按甲休兵，鎮撫趙民，百里之內，牛酒日至，以饗士大夫；", literal: "\" Lord Guangwu replied: \"For the general's plan at this moment, nothing surpasses laying by arms and resting the troops, pacifying the people of Zhao, and within a hundred li having oxen and wine arrive daily to feast the officers and men;", idiomatic: "\" Lord Guangwu replied: \"For your plan now, nothing surpasses laying by arms, resting your troops, pacifying the people of Zhao, and sending oxen and wine daily within a hundred li to feast your officers and men;" },
  { zh: "北首燕路，而後遣辨士奉咫尺之書，暴其所長於燕，燕必不敢不聽從。", literal: "face north toward the road to Yan, then send eloquent envoys bearing letters a foot long to display your strengths before Yan—Yan will surely not dare refuse to obey.", idiomatic: "face north toward Yan, then send eloquent envoys with a letter a foot long to display your strengths before Yan—Yan will not dare refuse." },
  { zh: "燕已從而東臨齊，雖有智者，亦不知為齊計矣。", literal: "Once Yan has submitted and you press east against Qi, though Qi has wise men, they will not know how to plan for Qi.", idiomatic: "Once Yan submits and you press east against Qi, though Qi has wise men, none will know how to plan for Qi." },
  { zh: "如是，則天下事皆可圖也。", literal: "If so, then all affairs under Heaven may be plotted.", idiomatic: "Then every affair under Heaven may be within your grasp." },
  { zh: "兵固有先聲而後實者，此之謂也。", literal: "In war there are indeed cases where reputation comes first and substance after—this is what is meant.", idiomatic: "In war reputation often precedes substance—this is what is meant.\"" },
  { zh: "」韓信曰：「善！", literal: "\" Han Xin said: \"Excellent!", idiomatic: "\" Han Xin said: \"Excellent!\"" },
  { zh: "」從其策，發使使燕，燕從風而靡；", literal: "\" He followed his plan, sent envoys to Yan, and Yan bent before the wind;", idiomatic: "\" He followed the plan, sent envoys to Yan, and Yan bent before the wind;" },
  { zh: "遣使報漢，且請以張耳王趙，漢王許之。", literal: "dispatched envoys to report to Han and also asked that Zhang Er be made king of Zhao; the king of Han granted it.", idiomatic: "reported to Han and asked that Zhang Er be made king of Zhao; the king of Han granted it." },
  { zh: "楚數使奇兵渡河擊趙，張耳、韓信往來救趙，因行定趙城邑，發兵詣漢。", literal: "Chu repeatedly sent picked troops across the river to strike Zhao; Zhang Er and Han Xin went back and forth to rescue Zhao, and in the course of their marches secured Zhao's cities and townships and sent troops to present themselves at Han.", idiomatic: "Chu repeatedly sent picked troops across the river against Zhao. Zhang Er and Han Xin marched back and forth to rescue Zhao, secured its cities and townships as they went, and sent troops to present themselves at Han." },
  { zh: "2甲戌晦，日有食之。", literal: "2. On the last day of jiaxu there was an eclipse of the sun.", idiomatic: "2. On the last day of jiaxu the sun was eclipsed." },
  { zh: "3十一月，癸卯晦，日有食之。", literal: "3. In the eleventh month, on the last day of guimao, there was an eclipse of the sun.", idiomatic: "3. In the eleventh month, on the last day of guimao, the sun was eclipsed." },
  { zh: "4隨何至九江，九江太宰主之，三日不得見。", literal: "4. Sui He reached Jiujiang; the grand steward of Jiujiang received him as host, yet for three days he was not granted audience.", idiomatic: "4. Sui He reached Jiujiang. The grand steward of Jiujiang received him, yet for three days he was not granted audience." },
  { zh: "隨何說太宰曰：「王之不見何，必以楚為強，以漢為弱也。", literal: "Sui He urged the grand steward: \"That the king does not see He must mean he holds Chu strong and Han weak.", idiomatic: "Sui He urged the grand steward: \"That your king will not see me must mean he holds Chu strong and Han weak." },
  { zh: "此臣之所以為使。", literal: "This is why your servant was sent as envoy.", idiomatic: "That is why I was sent.\"" },
  { zh: "使何得見，言之而是，大王所欲聞也；", literal: "If He is granted audience and what he says is right, it is what the great king wishes to hear;", idiomatic: "Grant me audience: if what I say is right, it is what your king wishes to hear;" },
  { zh: "言之而非，使何等二十人伏斧質九江市，足以明王倍漢而與楚也。", literal: "if what he says is wrong, let He and twenty others lie beneath the axe in the market of Jiujiang—enough to show the king turns from Han and joins Chu.", idiomatic: "if it is wrong, let me and twenty others lie beneath the axe in the market of Jiujiang—enough to show your king turns from Han and joins Chu.\"" },
  { zh: "」太宰乃言之王。", literal: "\" The grand steward then spoke of it to the king.", idiomatic: "\" The grand steward spoke to the king." },
  { zh: "王見之。", literal: "The king received him in audience.", idiomatic: "The king received him." },
  { zh: "隨何曰：「漢王使臣敬進書大王御者，竊怪大王與楚何親也。", literal: "Sui He said: \"The king of Han sent your servant respectfully to present a letter to the great king's attendants. Your servant marvels privately—what kinship does the great king share with Chu?", idiomatic: "Sui He said: \"The king of Han sent me to present a letter to your attendants. I marvel—what kinship do you share with Chu?\"" },
  { zh: "」九江王曰：「寡人北鄉而臣事之。", literal: "\" The king of Jiujiang said: \"Your servant faces north and serves him as subject.", idiomatic: "\" The king of Jiujiang said: \"I face north and serve him as subject.\"" },
  { zh: "」隨何曰：「大王與項王俱列為諸侯，北鄉而臣事之者，必以楚為強，可以托國也。", literal: "\" Sui He said: \"The great king and Lord Xiang were alike ranked as feudal lords. To face north and serve him as subject must mean you held Chu strong and fit to entrust your state.", idiomatic: "\" Sui He said: \"You and Lord Xiang were alike ranked as feudal lords. To face north and serve him must mean you held Chu strong enough to entrust your state to.\"" },
  { zh: "項王伐齊，身負版築，為士卒先。", literal: "Lord Xiang attacked Qi carrying earthworks on his back, going before the soldiers.", idiomatic: "Lord Xiang attacked Qi carrying earthworks on his back, going before his soldiers." },
  { zh: "大王宜悉九江之眾，身自將之，為楚前鋒；", literal: "The great king ought to have mustered all the forces of Jiujiang, led them in person, and served as Chu's vanguard;", idiomatic: "You ought to have mustered all Jiujiang's forces, led them yourself, and served as Chu's vanguard;" },
  { zh: "今乃發四千人以助楚。", literal: "yet you sent only four thousand men to aid Chu.", idiomatic: "yet you sent only four thousand men to aid Chu." },
  { zh: "夫北面而臣事人者，固若是乎？", literal: "For one who faces north and serves another as subject—is it truly thus?", idiomatic: "Is this how one faces north and serves another as subject?\"" },
  { zh: "漢王入彭城，項王未出齊也。", literal: "The king of Han entered Pengcheng while Lord Xiang had not yet left Qi.", idiomatic: "The king of Han entered Pengcheng while Lord Xiang had not yet left Qi." },
  { zh: "大王宜悉九江之兵渡淮，日夜會戰彭城下；", literal: "The great king ought to have mustered all Jiujiang's troops, crossed the Huai, and joined battle day and night beneath Pengcheng;", idiomatic: "You ought to have mustered all Jiujiang's troops, crossed the Huai, and fought day and night beneath Pengcheng;" },
  { zh: "大王乃撫萬人之眾，無一人渡淮者，垂拱而觀其孰勝。", literal: "yet the great king held ten thousand men and not one crossed the Huai—you folded your hands and watched which side would win.", idiomatic: "yet you held ten thousand men and not one crossed the Huai—you folded your hands and watched which side would win." },
  { zh: "夫托國於人者，固若是乎？", literal: "For one who entrusts his state to another—is it truly thus?", idiomatic: "Is this how one entrusts his state to another?\"" },
  { zh: "大王提空名以鄉楚而欲厚自托，臣竊為大王不取也！", literal: "The great king holds an empty name turned toward Chu yet wishes to secure himself richly upon him—your servant privately thinks the great king ought not take this!", idiomatic: "You hold an empty title turned toward Chu yet wish to secure yourself richly upon him—I think you ought not take this!\"" },
  { zh: "然而大王不背楚者，以漢為弱也。", literal: "Yet the reason the great king does not turn from Chu is that he holds Han weak.", idiomatic: "Yet you do not turn from Chu because you hold Han weak." },
  { zh: "夫楚兵雖強，天下負之以不義之名，以其背盟約而殺義帝也。", literal: "Chu's troops may be strong, but all under Heaven loads them with the name of unrighteousness because they broke the covenant and killed Emperor Yi.", idiomatic: "Chu's troops may be strong, but all under Heaven loads them with the name of unrighteousness—for they broke the covenant and killed Emperor Yi." },
  { zh: "漢王收諸侯，還守成皋、滎陽，下蜀、漢之粟，深溝壁壘，分卒守徼乘塞。", literal: "The king of Han has gathered the feudal lords, returned to hold Chenggao and Xingyang, drawn grain down from Shu and Han, dug deep trenches and raised ramparts, and divided soldiers to hold passes and guard barriers.", idiomatic: "The king of Han has gathered the lords, holds Chenggao and Xingyang, draws grain down from Shu and Han, digs deep trenches and raises ramparts, and stations men to hold every pass and barrier." },
  { zh: "楚人深入敵國八九百里，老弱轉糧千里之外。", literal: "Chu men have penetrated deep into enemy country eight or nine hundred li; the old and weak transport grain from a thousand li away.", idiomatic: "Chu has driven eight or nine hundred li into enemy country; the old and weak haul grain from a thousand li away." },
  { zh: "漢堅守而不動，楚進則不得攻，退則不能解，故曰楚兵不足恃也。", literal: "Han holds firm and does not stir; Chu advances yet cannot attack, retreats yet cannot disengage—thus it is said Chu's troops are not to be relied upon.", idiomatic: "Han holds firm and does not stir. Chu advances and cannot attack, retreats and cannot break free—thus Chu is not to be relied upon." },
  { zh: "使楚勝漢，則諸侯自危懼而相救。", literal: "If Chu were to defeat Han, the feudal lords would themselves grow fearful and rescue one another.", idiomatic: "If Chu defeats Han, every lord will grow fearful and rescue one another." },
  { zh: "夫楚之強，適足以致天下之兵耳。", literal: "Chu's strength would only suffice to summon the armies of all under Heaven.", idiomatic: "Chu's strength would only summon the armies of all under Heaven against it." },
  { zh: "故楚不如漢，其勢易見也。", literal: "Therefore Chu is not equal to Han—the trend is easy to see.", idiomatic: "Therefore Chu is not equal to Han—the trend is plain to see." },
  { zh: "今大王不與萬全之漢而自托於危亡之楚，臣竊為大王惑之！", literal: "Now the great king does not align with wholly secure Han yet entrusts himself to Chu in peril and ruin—your servant privately finds this perplexing for the great king!", idiomatic: "Now Your Majesty will not join wholly secure Han yet trusts perilous, doomed Chu—I cannot see why, for Your Majesty’s sake!" },
  { zh: "臣非以九江之兵足以亡楚也；", literal: "Your servant does not mean that Jiujiang’s troops suffice to destroy Chu;", idiomatic: "I do not claim that Jiujiang’s troops alone can destroy Chu;" },
  { zh: "大王發兵而倍楚，項王必留；", literal: "if the great king raises troops and turns against Chu, the King of Xiang will surely be held back;", idiomatic: "if Your Majesty raises troops and turns on Chu, the King of Xiang will surely be held;" },
  { zh: "留數月，漢之取天下可以萬全。", literal: "held for several months, Han’s taking of all under Heaven can be wholly secure.", idiomatic: "held for several months, Han’s conquest of the realm will be wholly assured." },
  { zh: "臣請與大王提劍而歸漢，漢王必裂地而封大王；", literal: "Your servant asks to return to Han with the great king, sword in hand; the King of Han will surely partition land and enfeoff the great king;", idiomatic: "I ask to return to Han with Your Majesty, swords in hand—the King of Han will surely enfeoff you with a share of territory;" },
  { zh: "又況九江必大王有也。", literal: "how much more must Jiujiang belong to the great king.", idiomatic: "and Jiujiang itself will surely remain yours." },
  { zh: "」九江王曰：「請奉命。", literal: "” The King of Jiujiang said: “I ask to receive the command.", idiomatic: "” The King of Jiujiang said, “I accept your orders." },
  { zh: "」陰許畔楚與漢，未敢洩也。", literal: "” He secretly agreed to turn from Chu and join Han but did not dare reveal it.", idiomatic: "” He secretly agreed to desert Chu for Han but dared not reveal it." },
  { zh: "楚使者在九江，舍傳舍，方急責布發兵。", literal: "Chu’s envoy was in Jiujiang, lodged at the relay inn, urgently pressing Bu to send troops.", idiomatic: "A Chu envoy was in Jiujiang, lodged at the relay station, urgently demanding that Bu send troops." },
  { zh: "隨何直入，坐楚使者上，曰：「九江王已歸漢，楚何以得發兵？", literal: "Sui He went straight in, seated himself above the Chu envoy, and said: “The King of Jiujiang has already submitted to Han—how can Chu obtain troops?", idiomatic: "Sui He went straight in, sat above the Chu envoy, and said, “The King of Jiujiang has already gone over to Han—how can Chu still demand troops?" },
  { zh: "」布愕然。", literal: "” Bu was startled.", idiomatic: "” Bu was stunned." },
  { zh: "楚使者起。", literal: "The Chu envoy rose.", idiomatic: "The Chu envoy rose." },
  { zh: "何因說布曰：「事已構，可遂殺楚使者，無使歸，而疾走漢並力。", literal: "He thereupon urged Bu, saying: “The affair is already set; you can at once kill the Chu envoy, not let him return, and hurry to Han to combine strength.", idiomatic: "Sui He then urged Bu: “The matter is settled—kill the Chu envoy at once, let none return, and hurry to Han to join forces." },
  { zh: "」布曰：「如使者教。", literal: "” Bu said: “As the envoy instructs.", idiomatic: "” Bu said, “As you advise." },
  { zh: "」於是殺楚使者，因起兵而攻楚。", literal: "” He thereupon killed the Chu envoy and raised troops to attack Chu.", idiomatic: "” He killed the Chu envoy and raised troops to attack Chu." },
  { zh: "楚使項聲、龍且攻九江，數月，龍且破九江軍。", literal: "Chu sent Xiang Sheng and Long Ju to attack Jiujiang; after several months Long Ju routed the Jiujiang army.", idiomatic: "Chu sent Xiang Sheng and Long Ju against Jiujiang; after several months Long Ju broke the Jiujiang army." },
  { zh: "布欲引兵走漢，恐楚兵殺之，乃間行與何俱歸漢。", literal: "Bu wished to lead his troops to Han but feared Chu troops would kill him; he therefore traveled by secret paths and returned to Han together with He.", idiomatic: "Bu meant to march to Han but feared Chu would kill him, so he slipped away by hidden paths and returned to Han with Sui He." },
  { zh: "十二月，九江王至漢。", literal: "In the twelfth month the King of Jiujiang reached Han.", idiomatic: "In the twelfth month the King of Jiujiang reached Han." },
  { zh: "漢王方踞床洗足，召布入見。", literal: "The King of Han was just then sitting on his bed washing his feet and summoned Bu to audience.", idiomatic: "The King of Han was sitting on his bed washing his feet when he summoned Bu to audience." },
  { zh: "布大怒，悔來，欲自殺；", literal: "Bu was greatly angry, regretted coming, and wished to kill himself;", idiomatic: "Bu flew into a rage, regretted coming, and meant to kill himself;" },
  { zh: "及出就舍，帳御、飲食、從官皆如漢王居，布又大喜過望。", literal: "when he went out to his lodging, tent attendants, food and drink, and follower-officials were all like the King of Han’s dwelling—Bu again rejoiced beyond expectation.", idiomatic: "but when he reached his quarters, tent servants, food, drink, and attendants all matched the King of Han’s own establishment, and Bu rejoiced beyond all hope." },
  { zh: "於是乃使人入九江；", literal: "He thereupon sent men into Jiujiang;", idiomatic: "He then sent men into Jiujiang;" },
  { zh: "楚已使項伯收九江兵，盡殺布妻子，布使者頗得故人、幸臣，將眾數千人歸漢。", literal: "Chu had already sent Xiang Bo to gather Jiujiang’s troops, killed all of Bu’s wife and children; Bu’s envoys fairly recovered old acquaintances and favored ministers and led several thousand men back to Han.", idiomatic: "Chu had already sent Xiang Bo to take over Jiujiang’s forces and had killed Bu’s wife and children; Bu’s envoys recovered many old friends and favored retainers and brought several thousand men back to Han." },
  { zh: "漢益九江王兵，與俱屯成皋。", literal: "Han reinforced the King of Jiujiang’s troops and stationed together with him at Chenggao.", idiomatic: "Han reinforced the King of Jiujiang’s forces and encamped with him at Chenggao." },
  { zh: "楚數侵奪漢甬道，漢軍乏食。", literal: "Chu repeatedly raided and seized Han’s supply corridor; the Han army lacked food.", idiomatic: "Chu repeatedly cut Han’s supply corridor, and the Han army ran short of food." },
  { zh: "漢王與酈食其謀橈楚權。", literal: "The King of Han with Li Yiji plotted to weaken Chu’s power.", idiomatic: "The King of Han consulted Li Yiji on how to weaken Chu." },
  { zh: "食其曰：「昔湯伐桀，封其後於杞；", literal: "Yiji said: “Formerly Tang attacked Jie and enfeoffed his descendant in Qi;", idiomatic: "Yiji said, “When Tang attacked Jie, he enfeoffed Jie’s descendant in Qi;" },
  { zh: "武王伐紂，封其後於宋。", literal: "King Wu attacked Zhou and enfeoffed his descendant in Song.", idiomatic: "when King Wu attacked Zhou, he enfeoffed Zhou’s descendant in Song." },
  { zh: "今秦失德棄義，侵伐諸侯，滅其社稷，使無立錐之地，陛下誠能復立六國之後，此其君臣、百姓必皆戴陛下之德，莫不鄉風慕義，願為臣妾。", literal: "Now Qin lost virtue and abandoned righteousness, invaded and attacked the feudal lords, destroyed their altars of soil and grain, leaving them no room to stand an awl—if Your Majesty can truly restore the descendants of the Six States, their rulers and ministers and common people will surely all bear Your Majesty’s virtue on their heads, none not turning toward the wind and admiring righteousness, wishing to be your subjects and handmaids.", idiomatic: "Qin lost the Way and abandoned righteousness, invaded the lords, and destroyed their states until they had not room to stand an awl—if Your Majesty will restore the heirs of the Six States, their rulers, ministers, and people will all honor your virtue, turn toward you, and gladly become your subjects." },
  { zh: "德義已行，陛下南鄉稱霸，楚必斂衽而朝。", literal: "Once virtue and righteousness are practiced, Your Majesty facing south to hegemony, Chu will surely gather its robes and attend court.”", idiomatic: "Once your virtue is shown, Your Majesty can face south as hegemon, and Chu will surely gather its robes and come to court.”" },
  { zh: "」漢王曰：「善！", literal: "” The King of Han said: “Good!", idiomatic: "” The King of Han said, “Excellent!" },
  { zh: "趣刻印，先生因行佩之矣。", literal: "Hurry to carve the seals; master, then go and wear them on your mission.”", idiomatic: "Carve the seals at once, Master, and take them on your mission.”" },
  { zh: "」食其未行，張良從外來謁。", literal: "” Before Yiji had set out, Zhang Liang came from outside to audience.", idiomatic: "” Before Yiji had left, Zhang Liang arrived from outside to pay his respects." },
  { zh: "漢王方食，曰：「子房前！", literal: "The King of Han was just eating and said: “Zifang, come forward!", idiomatic: "The King of Han was at his meal and said, “Zifang, come here!" },
  { zh: "客有為我計橈楚權者。", literal: "A guest has devised for me a plan to weaken Chu’s power.", idiomatic: "A guest has proposed a plan to weaken Chu." },
  { zh: "」具以酈生語告良，曰：「何如？", literal: "” He fully told Liang what Li Yiji had said and asked: “How is it?", idiomatic: "” He repeated Li Yiji’s words to Zhang Liang and asked, “What do you think?" },
  { zh: "」良曰：「誰為陛下畫此計者？", literal: "” Liang said: “Who drew this plan for Your Majesty?", idiomatic: "” Zhang Liang said, “Who devised this plan for Your Majesty?" },
  { zh: "陛下事去矣！", literal: "Your Majesty’s cause is lost!", idiomatic: "Your Majesty’s cause is lost!" },
  { zh: "」漢王曰：「何哉？", literal: "” The King of Han said: “How so?", idiomatic: "” The King of Han said, “Why?" },
  { zh: "」對曰：「臣請借前箸，為大王籌之。", literal: "” He replied: “Your servant asks to borrow the chopsticks before you and calculate for the great king.", idiomatic: "” He replied, “Let me borrow the chopsticks before you and reckon it out for Your Majesty." },
  { zh: "昔湯、武封桀、紂之後者，度能制其死生之命也；", literal: "Formerly Tang and Wu enfeoffed the descendants of Jie and Zhou because they estimated they could control their lives and deaths;", idiomatic: "Tang and Wu enfeoffed the heirs of Jie and Zhou because they knew they could control their lives and deaths;" },
  { zh: "今陛下能制項籍之死命乎？", literal: "can Your Majesty now control Xiang Ji’s life and death?", idiomatic: "can Your Majesty control Xiang Ji’s life and death?" },
  { zh: "其不可一也。", literal: "That is the first impossibility.", idiomatic: "That is the first reason it will not work." },
  { zh: "武王入殷，表商容之閭，釋箕子之囚，封比干之墓，今陛下能乎？", literal: "King Wu entered Yin, marked out the lane of Shang Rong, released Jizi from prison, and mounded Bi Gan’s tomb—can Your Majesty do so?", idiomatic: "King Wu entered Yin, honored Shang Rong’s lane, freed Jizi, and restored Bi Gan’s tomb—can Your Majesty do that?" },
  { zh: "其不可二也。", literal: "That is the second impossibility.", idiomatic: "That is the second reason." },
  { zh: "發巨橋之粟，散鹿台之錢，以賜貧窮，今陛下能乎？", literal: "He released the grain of Huge Bridge, scattered the money of Deer Terrace to bestow on the poor—can Your Majesty do so?", idiomatic: "He opened the Huge Bridge granaries and scattered the Deer Terrace treasure to the poor—can Your Majesty do that?" },
  { zh: "其不可三也。", literal: "That is the third impossibility.", idiomatic: "That is the third reason." },
  { zh: "殷事已畢，偃革為軒，倒載干戈，示天下不復用兵，今陛下能乎？", literal: "When Yin’s affairs were finished, he laid weapons aside to make chariots, inverted and carried spears and halberds, showing all under Heaven that arms would not be used again—can Your Majesty do so?", idiomatic: "When Yin was settled, he laid aside arms for chariots, inverted weapons on the wagons, and showed the realm that war would not resume—can Your Majesty do that?" },
  { zh: "其不可四也。", literal: "That is the fourth impossibility.", idiomatic: "That is the fourth reason." },
  { zh: "休馬華山之陽，示以無為，今陛下能乎？", literal: "He rested horses on the south of Mount Hua, showing non-action—can Your Majesty do so?", idiomatic: "He rested his horses on the sunny side of Mount Hua to show he would not act—can Your Majesty do that?" },
  { zh: "其不可五也。", literal: "That is the fifth impossibility.", idiomatic: "That is the fifth reason." },
  { zh: "放牛桃林之陰，以示不復輸積，今陛下能乎？", literal: "He released oxen in the shade of Peach Grove, showing he would not again transport stores—can Your Majesty do so?", idiomatic: "He turned his oxen loose in the shade of Peach Grove to show he would levy no more grain—can Your Majesty do that?" },
  { zh: "其不可六也。", literal: "That is the sixth impossibility.", idiomatic: "That is the sixth reason." },
  { zh: "天下游士，離其親戚，棄墳墓，去故舊，從陛下游者，徒欲日夜望咫尺之地；", literal: "Wandering scholars under Heaven left their kin, abandoned graves, forsook old friends, and followed Your Majesty in wanderings—they only wished day and night to glimpse a foot of territory;", idiomatic: "The wandering scholars who left kin, graves, and old ties to follow Your Majesty only want, day and night, a foot of land;" },
  { zh: "今復立六國之後，天下游士各歸事其主，從其親戚，反其故舊、墳墓，陛下與誰取天下乎？", literal: "if you now restore the descendants of the Six States, wandering scholars under Heaven will each return to serve their lords, follow their kin, and go back to old friends and graves—with whom will Your Majesty take all under Heaven?", idiomatic: "restore the Six States now, and every wandering scholar will return to his lord, his kin, his graves—with whom will Your Majesty win the realm?" },
  { zh: "其不可七也。", literal: "That is the seventh impossibility.", idiomatic: "That is the seventh reason." },
  { zh: "且夫楚唯無強，六國立者復橈而從之，陛下焉得而臣之？", literal: "Moreover, if Chu alone were not strong, once the Six States were established their rulers would again waver and follow it—how could Your Majesty make them your subjects?", idiomatic: "Moreover, unless Chu alone were strong, the restored Six States would waver and follow Chu again—how could Your Majesty make them your subjects?" },
  { zh: "其不可八也。", literal: "That is the eighth impossibility.", idiomatic: "That is the eighth reason." },
  { zh: "誠用客之謀，陛下事去矣！", literal: "If you truly employ the guest’s stratagem, Your Majesty’s cause is lost!", idiomatic: "If you truly follow the guest’s plan, Your Majesty’s cause is lost!" },
  { zh: "」漢王輟食，吐哺，罵曰：「豎儒幾敗而公事！", literal: "” The King of Han stopped eating, spat out his mouthful, and cursed: “The pedant nearly ruined my affairs!", idiomatic: "” The King of Han stopped eating, spat out his food, and cursed, “That pedant nearly ruined me!" },
  { zh: "」令趣銷印。", literal: "” He ordered that the seals be destroyed at once.", idiomatic: "” He ordered the seals destroyed at once." },
  { zh: "::荀悅論曰：夫立策決勝之術，其要有三：一曰形，二曰勢，三曰情。", literal: ":: Xun Yue’s commentary says: In the art of setting policy and deciding victory, the essentials are three: first, form; second, momentum; third, disposition.", idiomatic: ":: Xun Yue comments: The art of setting policy and deciding victory has three essentials: form, momentum, and disposition." },
  { zh: "形者，言其大體得失之數也；", literal: "Form means speaking of the calculus of overall gain and loss;", idiomatic: "Form means the calculus of overall gain and loss;" },
  { zh: "勢者，言其臨時之宜、進退之機也；", literal: "momentum means speaking of what suits the moment and the occasion to advance or withdraw;", idiomatic: "momentum means what suits the moment and the occasion to advance or withdraw;" },
  { zh: "情者，言其心志可否之實也。", literal: "disposition means speaking of the reality of whether minds and wills can or cannot.", idiomatic: "disposition means the reality of whether hearts and wills can be relied on." },
  { zh: "故策同、事等而功殊者，三術不同也。", literal: "Therefore when policies are the same and affairs equal yet achievements differ, it is because the three arts differ.", idiomatic: "When the policy is the same and the affair equal yet the outcome differs, the three arts differ." },
  { zh: "::初，張耳、陳餘說陳涉以復六國，自為樹黨；", literal: ":: At first Zhang Er and Chen Yu urged Chen She to restore the Six States, building a faction for themselves;", idiomatic: ":: At first Zhang Er and Chen Yu urged Chen She to restore the Six States and build a faction;" },
  { zh: "酈生亦說漢王。", literal: "Li Yiji also urged the King of Han.", idiomatic: "Li Yiji urged the King of Han as well." },
  { zh: "所以說者同而得失異者，陳涉之起，天下皆欲亡秦；", literal: "The reason the advocacy was the same yet gain and loss differed: when Chen She rose, all under Heaven wished to destroy Qin;", idiomatic: "The counsel was the same yet the outcome differed because when Chen She rose, all under Heaven wished to destroy Qin;" },
  { zh: "而楚、漢之分未有所定，今天下未必欲亡項也。", literal: "whereas the division of Chu and Han was not yet settled—today all under Heaven does not necessarily wish to destroy Xiang.", idiomatic: "whereas Chu and Han were not yet settled, and today the realm does not necessarily wish to destroy Xiang." },
  { zh: "故立六國，於陳涉，所謂多己之黨而益秦之敵也；", literal: "Therefore restoring the Six States, for Chen She, is what is called increasing one’s own faction and adding to Qin’s enemies;", idiomatic: "For Chen She, restoring the Six States meant enlarging his own faction and Qin’s enemies;" },
  { zh: "且陳涉未能專天下之地也，所謂取非其有以與於人，行虛惠而獲實福也。", literal: "moreover Chen She had not been able to monopolize the lands of all under Heaven—what is called taking what was not his to give to others, practicing empty favor yet obtaining real blessing.", idiomatic: "and Chen She had not yet held the realm—giving away what was not his, granting empty favors yet winning real gain." },
  { zh: "立六國，於漢王，所謂割己之有而以資敵，設虛名而受實禍也。", literal: "Restoring the Six States, for the King of Han, is what is called cutting what was his to supply the enemy, setting up empty names yet receiving real calamity.", idiomatic: "For the King of Han, restoring the Six States meant cutting his own holdings to arm the enemy, setting up empty titles yet suffering real harm." },
  { zh: "此同事而異形者也。", literal: "This is the same affair yet different form.", idiomatic: "This is the same affair under different form." },
  { zh: "::及宋義待秦、趙之斃，與昔卞莊刺虎同說者也。", literal: ":: As for Song Yi waiting for Qin and Zhao to exhaust each other, it is the same doctrine as when Bian Zhuangzi stabbed the tiger of old.", idiomatic: ":: Song Yi’s waiting for Qin and Zhao to wear each other out follows the same doctrine as Bian Zhuangzi’s tiger." },
  { zh: "施之戰國之時，鄰國相攻，無臨時之急，則可也。", literal: "Applied in the Warring States era, when neighboring states attacked one another without urgent crisis of the moment, it could do.", idiomatic: "In the Warring States, when neighbors fought with no immediate crisis, it could work." },
  { zh: "戰國之立，其日久矣，一戰勝敗，未必以存亡也；", literal: "The Warring States had stood long; one battle’s victory or defeat did not necessarily mean survival or destruction;", idiomatic: "The Warring States had stood long; one battle did not necessarily decide survival;" },
  { zh: "其勢非能急於亡敵國也；", literal: "their momentum could not urgently bring about the enemy state’s ruin;", idiomatic: "their momentum could not quickly destroy an enemy state;" },
  { zh: "進乘利，退自保，故累力待時，承敵之斃，其勢然也。", literal: "advance to seize advantage, withdraw to secure oneself—therefore amassing strength and awaiting the time, inheriting the enemy’s exhaustion: such was their momentum.", idiomatic: "advance for gain, withdraw for safety, amass strength, await the moment, and profit from the enemy’s exhaustion—that was their momentum." },
  { zh: "今楚、趙所起，其與秦勢不並立，安危之機，呼吸成變，進則定功，退則受禍。", literal: "Now what Chu and Zhao have raised cannot stand alongside Qin in power; the occasion of safety and peril changes with a breath—advance and achievement is settled, retreat and calamity is received.", idiomatic: "What Chu and Zhao now face cannot coexist with Qin; safety and peril shift with every breath—advance and you secure victory, retreat and you suffer ruin." },
  { zh: "此同事而異勢者也。", literal: "This is the same affair yet different momentum.", idiomatic: "This is the same affair under different momentum." },
  { zh: "::伐趙之役，韓信軍於泜水之上而趙不能敗。", literal: ":: In the campaign against Zhao, Han Xin’s army was on the River Ci and Zhao could not defeat it.", idiomatic: ":: In the campaign against Zhao, Han Xin held the army on the Ci and Zhao could not break him." },
  { zh: "彭城之難，漢王戰於睢水之上，士卒皆赴入睢水而楚兵大勝。", literal: "At the disaster of Pengcheng the King of Han fought on the River Sui; soldiers all rushed into the Sui and Chu troops won a great victory.", idiomatic: "At Pengcheng the King of Han fought on the Sui; his men plunged into the river and Chu won a great victory." },
  { zh: "何則？", literal: "Why?", idiomatic: "Why?" },
  { zh: "趙兵出國迎戰，見可而進，知難而退，懷內顧之心，無出死之計；", literal: "Zhao’s troops went out of the state to meet battle—seeing advantage they advanced, knowing hardship they withdrew, harboring hearts that looked homeward, without plans to stake their lives;", idiomatic: "Zhao marched out to fight, advancing when it looked easy and retreating when hard, hearts turned homeward, with no mind to die;" },
  { zh: "韓信軍孤在水上，士卒必死，無有二心，此信之所以勝也。", literal: "Han Xin’s army stood alone on the water; soldiers had to die with no second heart—this is why Xin won.", idiomatic: "Han Xin’s army stood alone on the water; his men had to fight to the death with one mind—that is why Xin won." },
  { zh: "漢王深入敵國，置酒高會，士卒逸豫，戰心不固；", literal: "The King of Han penetrated deep into enemy country, set wine and held high feasts; soldiers were at ease and merry, battle hearts not firm;", idiomatic: "The King of Han had penetrated deep into enemy territory, feasting at leisure; his men were relaxed and their will to fight unsettled;" },
  { zh: "楚以強大之威而喪其國都，士卒皆有憤激之氣，救敗赴亡之急，以決一旦之命，此漢之所以敗也。", literal: "Chu, with mighty prestige, had lost its capital; soldiers all had indignant, aroused spirits, the urgency of rescuing defeat and rushing to ruin, to decide a single day’s fate—this is why Han was defeated.", idiomatic: "Chu, though mighty, had lost its capital; its soldiers burned with outrage and rushed to redeem defeat in one desperate stroke—that is why Han was beaten." },
  { zh: "且韓信選精兵以守，而趙以內顧之士攻之；", literal: "Moreover Han Xin chose elite troops to defend while Zhao attacked with men who looked inward;", idiomatic: "Han Xin chose elite troops to hold the line while Zhao attacked with men looking homeward;" },
  { zh: "項羽選精兵以攻，而漢以怠惰之卒應之，此同事而異情者也。", literal: "Xiang Yu chose elite troops to attack while Han met him with slack, indolent soldiers—this is the same affair yet different disposition.", idiomatic: "Xiang Yu chose elite troops to attack while Han met him with slack men—this is the same affair under different disposition." },
  { zh: "::故曰：權不可豫設，變不可先圖。", literal: ":: Therefore it is said: authority cannot be preset, change cannot be plotted in advance.", idiomatic: ":: Hence the saying: power cannot be preset, change cannot be plotted ahead of time." },
  { zh: "與時遷移，應物變化，設策之機也。", literal: "Shift with the times, respond to things as they change—that is the occasion for setting policy.", idiomatic: "Shift with the times and respond to things as they change—that is the moment for setting policy." },
  { zh: "5漢王謂陳平曰：「天下紛紛，何時定乎？", literal: "5. The King of Han said to Chen Ping: “All under Heaven is in turmoil—when will it be settled?", idiomatic: "5. The King of Han said to Chen Ping, “The realm is in turmoil—when will it be settled?" },
  { zh: "」陳平曰：「項王骨鯁之臣亞父、鍾離昧、龍且、周殷之屬，不過數人耳。", literal: "” Chen Ping said: “The King of Xiang’s blunt, loyal ministers—the Senior Lord, Zhongli Mo, Long Ju, Zhou Yin, and their kind—are no more than a few men.", idiomatic: "” Chen Ping said, “The King of Xiang’s stalwart ministers—the Senior Lord, Zhongli Mo, Long Ju, Zhou Yin, and the like—are only a few men." },
  { zh: "大王誠能捐數萬斤金，行反間，間其君臣，以疑其心。", literal: "If the great king can truly give up tens of thousands of jin of gold, run a counter-intelligence scheme, sow discord among their ruler and ministers, and make their hearts doubtful,", idiomatic: "If Your Majesty will truly spend tens of thousands of jin of gold on a counter-intelligence scheme, sow discord among their ruler and ministers, and make them doubt one another," },
  { zh: "項王為人，意忌信讒，必內相誅，漢因舉兵而攻之，破楚必矣。", literal: "the King of Xiang by nature is suspicious and trusts slander; he will surely execute one another within, and Han can thereupon raise troops and attack—breaking Chu is certain.”", idiomatic: "the King of Xiang is suspicious and trusts slander; he will surely turn on his own, and Han can then attack—Chu will surely be broken.”" },
  { zh: "」漢王曰：「善！", literal: "” The King of Han said: “Good!", idiomatic: "” The King of Han said, “Well said!" },
  { zh: "」乃出黃金四萬斤與平，恣所為，不問其出入。", literal: "” He thereupon gave Ping forty thousand jin of yellow gold, letting him do as he wished without questioning income or outgo.", idiomatic: "” He gave Ping forty thousand jin of gold and let him spend it as he pleased without accounting." },
  { zh: "平多以金縱反間於楚軍，宣言：「諸將鍾離昧等為項王將，功多矣，然而終不得裂地而王，欲與漢為一，以滅項氏而分王其地。", literal: "Ping largely used gold to spread counter-intelligence in the Chu army, proclaiming: “The generals Zhongli Mo and others serve as the King of Xiang’s commanders with many achievements, yet in the end they do not receive partitioned land and kingship—they wish to unite with Han to destroy the Xiang house and divide its territory as kings.", idiomatic: "Ping spent much of the gold spreading rumors in the Chu army: “Generals such as Zhongli Mo have served the King of Xiang with great merit yet never received a kingdom—they wish to join Han, destroy the Xiang house, and divide its lands among themselves." },
  { zh: "」項王果意不信鍾離昧等。", literal: "” The King of Xiang truly grew suspicious and did not trust Zhongli Mo and the others.", idiomatic: "” The King of Xiang grew suspicious and no longer trusted Zhongli Mo and the others." },
  { zh: "夏，四月，楚圍漢王於滎陽，急；", literal: "In summer, the fourth month, Chu besieged the King of Han at Yingyang; the situation was urgent;", idiomatic: "In summer, the fourth month, Chu besieged the King of Han at Yingyang, and the situation grew desperate;" },
  { zh: "漢王請和，割滎陽以西者為漢。", literal: "the King of Han sought peace, ceding the lands west of Yingyang to Han.", idiomatic: "the King of Han sued for peace, offering the territory west of Yingyang to Han." },
  { zh: "亞父勸羽急攻滎陽；", literal: "The Second Father urged Yu to press the attack on Yingyang at once;", idiomatic: "Fan Zeng urged Xiang Yu to press the attack on Yingyang at once;" },
  { zh: "漢王患之。", literal: "the King of Han was troubled by this.", idiomatic: "the King of Han was deeply troubled." },
  { zh: "項羽使使至漢，陳平使為太牢具。", literal: "Xiang Yu sent an envoy to Han; Chen Ping had a full grand feast prepared.", idiomatic: "Xiang Yu sent an envoy to Han; Chen Ping had a full grand feast prepared." },
  { zh: "舉進，見楚使，即佯驚曰：「吾以為亞父使，乃項王使。", literal: "He raised it and advanced; seeing the Chu envoy, he at once feigned alarm and said: “I thought this was the Second Father’s envoy—it is the King of Xiang’s envoy.", idiomatic: "He brought it forward; seeing the Chu envoy, he feigned alarm and said: “I thought this was Fan Zeng’s envoy—it is the King of Xiang’s envoy.”" },
  { zh: "」復持去，更以惡草具進楚使。", literal: "” He took it away again and instead presented the Chu envoy with a coarse grass meal.", idiomatic: "” He took it away and instead served the Chu envoy a coarse meal." },
  { zh: "楚使歸，具以報項王，項王果大疑亞父。", literal: "The Chu envoy returned and reported everything to the King of Xiang; the King of Xiang indeed came to suspect the Second Father greatly.", idiomatic: "The Chu envoy returned and reported everything to Xiang Yu, who indeed grew deeply suspicious of Fan Zeng." },
  { zh: "亞父欲急攻下滎陽城，項王不信，不肯聽。", literal: "The Second Father wished to press the attack and take Yingyang city at once; the King of Xiang did not trust him and would not heed him.", idiomatic: "Fan Zeng wished to press the attack and take Yingyang at once; Xiang Yu did not trust him and refused to listen." },
  { zh: "亞父聞項王疑之，乃怒曰：「天下事大定矣，君王自為之，願請骸骨！", literal: "The Second Father, hearing that the King of Xiang suspected him, thereupon said in anger: “The affairs of All under Heaven are nearly settled; let the kingly lord handle them himself—I beg leave to return my bones!", idiomatic: "When Fan Zeng heard that Xiang Yu suspected him, he said in anger: “The realm is nearly settled; handle it yourself—I beg leave to retire!”" },
  { zh: "」歸，未至彭城，疽發背而死。", literal: "” He returned; before reaching Pengcheng, a carbuncle broke out on his back and he died.", idiomatic: "” He set out for home; before reaching Pengcheng a carbuncle broke out on his back and he died." },
  { zh: "五月，將軍紀信言於漢王曰：「事急矣！", literal: "In the fifth month, General Ji Xin spoke to the King of Han, saying: “The affair is urgent!", idiomatic: "In the fifth month, General Ji Xin said to the King of Han: “Matters are desperate!”" },
  { zh: "臣請誑楚，王可以間出。", literal: "Your servant begs to deceive Chu; the king may slip out through the gap.", idiomatic: "Let me deceive Chu, and Your Majesty may slip out through the gap.”" },
  { zh: "」於是陳平夜出女子東門二千餘人，楚因而四面擊之。", literal: "” Thereupon Chen Ping sent out more than two thousand women by night through the east gate; Chu thereupon struck from all four sides.", idiomatic: "” Chen Ping then sent more than two thousand women out through the east gate by night; Chu attacked from all four sides." },
  { zh: "紀信乃乘王車，黃屋左纛，曰：「食盡，漢王降楚。", literal: "Ji Xin then rode the king’s carriage with the yellow canopy and left banner-fork and said: “Food is exhausted; the King of Han surrenders to Chu.", idiomatic: "Ji Xin then rode the king’s carriage with the yellow canopy and left banner-fork and cried: “Our food is gone—the King of Han surrenders to Chu!”" },
  { zh: "」楚皆呼萬歲，之城東觀。", literal: "” All Chu cried “Long live!” and went to the east of the city to watch.", idiomatic: "” The Chu troops all shouted “Long live!” and flocked east of the city to watch." },
  { zh: "以故漢王得與數十騎出西門遁去，令韓王信與周苛、魏豹、樅公守滎陽。", literal: "Because of this the King of Han was able to escape through the west gate with several dozen horsemen; he ordered King Xin of Han, Zhou Ke, Wei Bao, and Lord Cong to hold Yingyang.", idiomatic: "Thus the King of Han escaped through the west gate with several dozen horsemen and left King Xin of Han, Zhou Ke, Wei Bao, and Lord Cong to hold Yingyang." },
  { zh: "羽見紀信，問：「漢王安在？", literal: "Yu saw Ji Xin and asked: “Where is the King of Han?", idiomatic: "Yu saw Ji Xin and asked: “Where is the King of Han?”" },
  { zh: "」曰：「已出去矣。", literal: "” He said: “He has already gone out.", idiomatic: "” He said: “He has already escaped.”" },
  { zh: "」羽燒殺信。", literal: "” Yu burned Ji Xin to death.", idiomatic: "” Yu had Xin burned alive." },
  { zh: "周苛、樅公相謂曰：「反國之王，難與守城。", literal: "Zhou Ke and Lord Cong said to each other: “A king of a rebel state—hard to hold a city with him.", idiomatic: "Zhou Ke and Lord Cong said to each other: “A king of a rebel state—we cannot hold the city with him.”" },
  { zh: "」因殺魏豹。", literal: "” They thereupon killed Wei Bao.", idiomatic: "” They then killed Wei Bao." },
  { zh: "漢王出滎陽，至成皋，入關，收兵欲復東。", literal: "The King of Han left Yingyang, reached Chenggao, entered the passes, gathered troops, and wished to march east again.", idiomatic: "The King of Han left Yingyang, reached Chenggao, entered the passes, gathered troops, and prepared to march east again." },
  { zh: "轅生說漢王曰：「漢與楚相距滎陽數歲，漢常困。", literal: "Yuan Sheng urged the King of Han, saying: “Han and Chu have faced each other at Yingyang for several years; Han is often hard pressed.", idiomatic: "Yuan Sheng urged the King of Han: “Han and Chu have faced each other at Yingyang for years; Han is always hard pressed." },
  { zh: "願君王出武關，項王必引兵南走。", literal: "I beg the kingly lord to go out through Wu Pass; the King of Xiang is sure to lead his troops south in pursuit.", idiomatic: "March out through Wu Pass; Xiang Yu is sure to lead his troops south in pursuit." },
  { zh: "王深壁勿戰，令滎陽、成皋間且得休息，使韓信等得安輯河北趙地，連燕、齊，君王乃復走滎陽。", literal: "The king should fortify deeply and not fight, letting the region between Yingyang and Chenggao gain rest, allowing Han Xin and the rest to settle and organize Hebei and Zhao, link Yan and Qi, and then the kingly lord may again hasten to Yingyang.", idiomatic: "Fortify deeply and do not fight, so the region between Yingyang and Chenggao may rest and Han Xin may settle Hebei and Zhao, link Yan and Qi; then Your Majesty may hurry back to Yingyang." },
  { zh: "如此，則楚所備者多，力分；", literal: "If it is so, then what Chu must guard against will be many and its strength divided;", idiomatic: "Then Chu must guard many fronts and its strength will be divided;" },
  { zh: "漢得休息，復與之戰，破之必矣！", literal: "Han will gain rest; when it fights Chu again, defeating it is certain!", idiomatic: "Han will rest, and when it fights again, victory is certain!”" },
  { zh: "」漢王從其計，出軍宛、葉間。", literal: "” The King of Han followed this plan and led his army out between Wan and Ye.", idiomatic: "” The King of Han followed this plan and led his army out between Wan and Ye." },
  { zh: "與黥布行收兵。", literal: "He marched with Qing Bu gathering troops.", idiomatic: "He marched with Qing Bu gathering troops." },
  { zh: "羽聞漢王在宛，果引兵南；", literal: "Yu, hearing the King of Han was at Wan, indeed led his troops south;", idiomatic: "When Yu heard the King of Han was at Wan, he indeed led his troops south;" },
  { zh: "漢王堅壁不與戰。", literal: "the King of Han fortified firmly and would not give battle.", idiomatic: "the King of Han fortified firmly and refused battle." },
  { zh: "漢王之敗彭城，解而西也，彭越皆亡其所下城，獨將其兵北居河上，常往來為漢遊兵擊楚，絕其後糧。", literal: "When the King of Han was defeated at Pengcheng and withdrew west, Peng Yue abandoned every city he had taken and alone led his troops north to dwell on the river, constantly moving back and forth as Han’s roving troops to strike Chu and cut off its rear supplies.", idiomatic: "After the King of Han’s defeat at Pengcheng and withdrawal west, Peng Yue abandoned every city he had taken and alone led his troops north to the river, constantly raiding as Han’s roving force to strike Chu and cut its rear supplies." },
  { zh: "是月，彭越渡睢，與項聲、薛公戰下邳，破，殺薛公。", literal: "That month Peng Yue crossed the Sui, fought Xiang Sheng and Lord Xue at Xiapi, routed them, and killed Lord Xue.", idiomatic: "That month Peng Yue crossed the Sui, fought Xiang Sheng and Lord Xue at Xiapi, routed them, and killed Lord Xue." },
  { zh: "羽乃使終公守成皋，而自東擊彭越。", literal: "Yu then sent Lord Zhong to hold Chenggao and himself marched east to attack Peng Yue.", idiomatic: "Yu sent Lord Zhong to hold Chenggao and marched east himself to attack Peng Yue." },
  { zh: "漢王引兵北，擊破終公，復軍成皋。", literal: "The King of Han led his troops north, defeated and broke Lord Zhong, and re-established his army at Chenggao.", idiomatic: "The King of Han led his troops north, defeated Lord Zhong, and re-established his army at Chenggao." },
  { zh: "六月，羽已破走彭越，聞漢復軍成皋，乃引兵西拔滎陽城，生得周苛。", literal: "In the sixth month, Yu having already routed Peng Yue, heard that Han had re-established its army at Chenggao; he thereupon led his troops west, took Yingyang city, and captured Zhou Ke alive.", idiomatic: "In the sixth month, having routed Peng Yue, Yu heard that Han had re-established its army at Chenggao; he marched west, took Yingyang, and captured Zhou Ke alive." },
  { zh: "羽謂苛：「為我將，以公為上將軍，封三萬戶。", literal: "Yu said to Ke: “Serve as my general—I will make you Grand General with a fief of thirty thousand households.", idiomatic: "Yu said to Ke: “Serve as my general—I will make you Grand General with a fief of thirty thousand households.”" },
  { zh: "」周苛罵曰：「若不趨降漢，今為虜矣；", literal: "” Zhou Ke cursed, saying: “If you do not hurry to surrender to Han, you will now be a captive;", idiomatic: "” Zhou Ke cursed: “If you do not hurry to surrender to Han, you will be a captive now;" },
  { zh: "若非漢王敵也！", literal: "you are no match for the King of Han!", idiomatic: "you are no match for the King of Han!”" },
  { zh: "」羽烹周苛，並殺樅公而虜韓王信，遂圍成皋。", literal: "” Yu boiled Zhou Ke alive, also killed Lord Cong and captured King Xin of Han, and thereupon besieged Chenggao.", idiomatic: "” Yu boiled Zhou Ke alive, killed Lord Cong, captured King Xin of Han, and besieged Chenggao." },
  { zh: "漢王逃，獨與滕公共車出成皋玉門，北渡河，宿小脩武傳舍。", literal: "The King of Han fled; he alone shared a carriage with the Lord of Teng out through Chenggao’s Jade Gate, crossed the river north, and lodged at an inn in Xiaoxiuwu.", idiomatic: "The King of Han fled alone in a carriage with the Lord of Teng through Chenggao’s Jade Gate, crossed the river north, and lodged at an inn in Xiaoxiuwu." },
  { zh: "晨，自稱漢使，馳入趙壁。", literal: "At dawn he called himself an envoy of Han and galloped into the Zhao camp.", idiomatic: "At dawn he called himself an envoy of Han and galloped into the Zhao camp." },
  { zh: "張耳、韓信未起，即其臥內，奪其印符以麾召諸將，易置之。", literal: "Zhang Er and Han Xin had not yet risen; he went straight into their sleeping quarters, seized their seals and tallies, and with a wave summoned the generals and reassigned them.", idiomatic: "Zhang Er and Han Xin had not yet risen; he went into their quarters, seized their seals and tallies, summoned the generals with a wave, and reassigned them." },
  { zh: "信、耳起，乃知漢王來，大驚。", literal: "When Xin and Er rose, they then knew the King of Han had come and were greatly startled.", idiomatic: "When Xin and Er rose and learned the King of Han had come, they were astonished." },
  { zh: "漢王既奪兩人軍，即令張耳徇行，備守趙地。", literal: "The King of Han, having seized the armies of both men, at once ordered Zhang Er to march through and guard Zhao territory.", idiomatic: "Having seized both armies, the King of Han ordered Zhang Er to march through and guard Zhao." },
  { zh: "拜韓信為相國，收趙兵未發者擊齊。", literal: "He appointed Han Xin Chancellor of State and gathered Zhao troops not yet sent forth to attack Qi.", idiomatic: "He appointed Han Xin Chancellor of State and gathered Zhao’s remaining troops to attack Qi." },
  { zh: "諸將稍稍得出成皋從漢王。", literal: "The generals gradually were able to get out of Chenggao and follow the King of Han.", idiomatic: "The generals gradually escaped Chenggao and rejoined the King of Han." },
  { zh: "楚拔成皋，欲西；", literal: "Chu took Chenggao and wished to go west;", idiomatic: "Chu took Chenggao and wished to march west;" },
  { zh: "漢使兵距之鞏，令其不得西。", literal: "Han sent troops to block it at Gong and would not let it go west.", idiomatic: "Han sent troops to block it at Gong and would not let it advance west." },
  { zh: "6秋，七月，有星孛於大角。", literal: "6. In autumn, the seventh month, a broom star appeared at Great Horn.", idiomatic: "6. In autumn, the seventh month, a broom star appeared at Great Horn." },
  { zh: "7臨江王敖薨，子尉嗣。", literal: "7. King Ao of Linjiang died; his son Wei succeeded.", idiomatic: "7. King Ao of Linjiang died; his son Wei succeeded." },
  { zh: "8漢王得韓信軍，復大振。", literal: "8. The King of Han obtained Han Xin’s army and again was greatly revived.", idiomatic: "8. The King of Han obtained Han Xin’s army and his fortunes revived greatly." },
  { zh: "八月，引兵臨河，南鄉，軍小脩武，欲復與楚戰。", literal: "In the eighth month he led his troops to the river, faced south, encamped at Xiaoxiuwu, and wished to fight Chu again.", idiomatic: "In the eighth month he led his troops to the river, faced south, encamped at Xiaoxiuwu, and prepared to fight Chu again." },
  { zh: "郎中鄭忠說止漢王，使高壘深塹勿與戰。", literal: "Gentleman-of-the-Palace Zheng Zhong urged the King of Han to stop, building high ramparts and deep moats and not giving battle.", idiomatic: "Gentleman-of-the-Palace Zheng Zhong urged the King of Han to hold back, build high ramparts and deep moats, and not give battle." },
  { zh: "漢王聽其計，使將軍劉賈、盧綰將卒二萬人，騎數百，度白馬津，入楚地，佐彭越，燒楚積聚，以破其業，無以給項王軍食而已。", literal: "The King of Han heeded this plan and sent Generals Liu Jia and Lu Wan to command twenty thousand soldiers and several hundred horsemen to cross the White Horse Ford, enter Chu territory, assist Peng Yue, and burn Chu’s stores—only to break its enterprise and leave nothing to supply the King of Xiang’s army with food.", idiomatic: "The King of Han heeded this plan and sent Generals Liu Jia and Lu Wan with twenty thousand foot and several hundred horsemen across the White Horse Ford into Chu to assist Peng Yue, burn Chu’s stores, break its enterprise, and leave nothing to feed Xiang Yu’s army." },
  { zh: "楚兵擊劉賈，賈輒堅壁不肯與戰，而與彭越相保。", literal: "Chu troops attacked Liu Jia; Jia at once fortified firmly and would not give battle, but sheltered with Peng Yue.", idiomatic: "Chu attacked Liu Jia; Jia fortified firmly and refused battle, sheltering with Peng Yue." },
  { zh: "9彭越攻徇梁地，下睢陽、外黃等十七城。", literal: "9. Peng Yue attacked and overran Liang territory, taking Suiyang, Waihuang, and seventeen other cities.", idiomatic: "9. Peng Yue overran Liang territory, taking Suiyang, Waihuang, and seventeen other cities." },
  { zh: "九月，項王謂大司馬曹咎曰：「謹守成皋。", literal: "In the ninth month the King of Xiang said to Grand Marshal Cao Jiu: “Guard Chenggao carefully.", idiomatic: "In the ninth month Xiang Yu told Grand Marshal Cao Jiu: “Guard Chenggao carefully." },
  { zh: "即漢王欲挑戰，慎勿與戰，勿令得東而已。", literal: "Even if the King of Han wishes to offer battle, be careful not to fight—only do not let him get east.", idiomatic: "Even if the King of Han offers battle, do not fight—only do not let him advance east.”" },
  { zh: "我十五日必定梁地，復從將軍。", literal: "Within fifteen days I am certain to settle Liang territory and rejoin you, general.", idiomatic: "Within fifteen days I will settle Liang and rejoin you.”" },
  { zh: "」羽引兵東行，擊陳留、外黃、睢陽等城，皆下之。", literal: "” Yu led his troops east, attacked Chenliu, Waihuang, Suiyang, and other cities, and took them all.", idiomatic: "” Yu marched east, attacked Chenliu, Waihuang, Suiyang, and other cities, and took them all." },
  { zh: "漢王欲捐成皋以東，屯鞏、洛以距楚。", literal: "The King of Han wished to abandon the lands east of Chenggao and encamp at Gong and Luo to resist Chu.", idiomatic: "The King of Han wished to abandon the lands east of Chenggao and encamp at Gong and Luo to resist Chu." },
  { zh: "酈生曰：「臣聞『知天之天者，王事可成』，王者以民為天，而民以食為天。", literal: "Li Yiji said: “Your servant has heard ‘He who knows Heaven’s Heaven can accomplish kingly affairs’—a king takes the people as Heaven, and the people take food as Heaven.", idiomatic: "Li Yiji said: “I have heard that ‘he who knows Heaven’s Heaven can accomplish kingly affairs’—a king takes the people as Heaven, and the people take food as Heaven." },
  { zh: "夫敖倉，天下轉輸久矣，臣聞其下乃有藏粟甚多。", literal: "As for Aocang, it has long been the hub of transport for All under Heaven; your servant hears that beneath it stored grain is very abundant.", idiomatic: "Aocang has long been the realm’s transport hub; I hear that beneath it grain is stored in great abundance." },
  { zh: "楚人拔滎陽，不堅守敖倉，乃引而東，令適卒分守成皋，此乃天所以資漢也。", literal: "The Chu men took Yingyang yet did not hold Aocang firmly; they drew east instead and had conscript soldiers divide and hold Chenggao—this is Heaven’s means to supply Han.", idiomatic: "Chu took Yingyang yet did not hold Aocang firmly; they marched east and left conscripts to hold Chenggao—this is Heaven supplying Han." },
  { zh: "方今楚易取而漢反卻，自奪其便，臣竊以為過矣。", literal: "Now Chu is easy to take while Han instead retreats—self-depriving its advantage; your servant privately considers this a fault.", idiomatic: "Now Chu is easy to take while Han retreats instead—throwing away its advantage; I consider this a mistake." },
  { zh: "且兩雄不俱立，楚、漢久相持不決，海內搖蕩，農夫釋耒，紅女下機，天下之心未有所定也。", literal: "Moreover, two heroes cannot stand together; Chu and Han have long faced each other without decision—the realm shakes, farmers lay down their plows, women in red leave their looms, and the hearts of All under Heaven are not yet settled.", idiomatic: "Moreover, two heroes cannot stand together; Chu and Han have long faced each other without decision—the realm shakes, farmers lay down their plows, women leave their looms, and the hearts of the realm are not yet settled." },
  { zh: "願足下急復進兵，收取滎陽，據敖倉之粟，塞成皋之險，杜太行之道，距蜚狐之口，守白馬之津，以示諸侯形制之勢，則天下知所歸矣。", literal: "I beg you, sir, urgently to advance your troops again, take Yingyang, hold Aocang’s grain, block Chenggao’s passes, shut the road through Taihang, hold Feihu’s mouth, guard the White Horse Ford, and show the feudal lords the pattern of power—then All under Heaven will know where to turn.", idiomatic: "I beg you urgently to advance again, take Yingyang, hold Aocang’s grain, block Chenggao’s passes, shut the Taihang road, hold Feihu’s mouth, guard the White Horse Ford, and show the lords the pattern of power—then the realm will know where to turn.”" },
  { zh: "」王從之，乃復謀取敖倉。", literal: "” The king followed this and thereupon planned again to take Aocang.", idiomatic: "” The king followed this and planned again to take Aocang." },
  { zh: "食其又說王曰：「方今燕、趙已定，唯齊未下，諸田宗強，負海、岱，阻河、濟，南近於楚，人多變詐；", literal: "Shi again urged the king, saying: “Now Yan and Zhao are already settled; only Qi is not yet taken. The Tian clans of Qi are strong, backed by the sea and Mount Dai, blocked by the Yellow River and the Ji, close to Chu in the south, and their people are much given to shifting deceit;", idiomatic: "Shi again urged the king: “Yan and Zhao are settled; only Qi remains. The Tian clans are strong, backed by the sea and Mount Dai, blocked by the Yellow River and the Ji, close to Chu in the south, and their people are crafty and shifting;" },
  { zh: "足下雖遣數萬師，未可以歲月破也。", literal: "even if you, sir, send tens of thousands of troops, they cannot be broken in months and years.", idiomatic: "even if you send tens of thousands of troops, they cannot be broken in months.”" },
  { zh: "臣請得奉明詔說齊王，使為漢而稱東籓。", literal: "Your servant begs to receive your clear command and persuade the King of Qi to serve Han and style himself eastern vassal.", idiomatic: "Let me carry your command and persuade the King of Qi to serve Han as eastern vassal.”" },
  { zh: "」上曰：「善！", literal: "” The sovereign said: “Excellent!", idiomatic: "” The sovereign said: “Excellent!”" },
  { zh: "」乃使酈生說齊王曰：「王知天下之所歸乎？", literal: "” He then sent Li Yiji to persuade the King of Qi, saying: “Does the king know where All under Heaven is turning?", idiomatic: "” He sent Li Yiji to persuade the King of Qi: “Do you know where the realm is turning?”" },
  { zh: "」王曰：「不知也。", literal: "” The king said: “I do not know.", idiomatic: "” The king said: “I do not.”" },
  { zh: "天下何所歸？", literal: "Where is All under Heaven turning?", idiomatic: "Where is the realm turning?”" },
  { zh: "」酈生曰：「歸漢。", literal: "” Li Yiji said: “To Han.", idiomatic: "” Li Yiji said: “To Han.”" },
  { zh: "」曰：「先生何以言之？", literal: "” He said: “How does the gentleman say this?", idiomatic: "” He said: “On what grounds, sir?”" },
  { zh: "」曰：「漢王先入咸陽，項王負約，王之漢中。", literal: "” He said: “The King of Han entered Xianyang first; the King of Xiang broke the covenant and made him king in Hanzhong.", idiomatic: "” He said: “The King of Han entered Xianyang first; Xiang Yu broke the covenant and made him king in Hanzhong." },
  { zh: "項王遷殺義帝，漢王聞之，起蜀、漢之兵擊三秦，出關而責義帝之處。", literal: "The King of Xiang moved and killed Emperor Yi; the King of Han, hearing this, raised the troops of Shu and Han to strike the Three Qin, went out through the passes, and held the King of Xiang to account for Emperor Yi’s fate.", idiomatic: "Xiang Yu moved and killed Emperor Yi; the King of Han, hearing this, raised the troops of Shu and Han, struck the Three Qin, went out through the passes, and held him to account for Emperor Yi.”" },
  { zh: "收天下之兵，立諸侯之後；", literal: "He gathered the arms of All under Heaven and installed the heirs of the feudal lords;", idiomatic: "He gathered the realm’s arms and installed the heirs of the feudal lords;" },
  { zh: "降城即以侯其將，得賂即以分其士；", literal: "when a city surrendered he at once enfeoffed its general, and when booty was taken he at once divided it among his soldiers;", idiomatic: "when a city surrendered he enfeoffed its general at once, and when booty was taken he divided it among his soldiers at once;" },
  { zh: "與天下同其利，豪英賢才皆樂為之用。", literal: "he shared the profits of All under Heaven, and heroes and worthy talents all rejoiced to serve him.", idiomatic: "he shared the realm’s profits, and heroes and worthy talents all rejoiced to serve him." },
  { zh: "項王有倍約之名，殺義帝之實；", literal: "The King of Xiang has the name of breaking covenants and the fact of killing Emperor Yi;", idiomatic: "Xiang Yu has the name of breaking covenants and the fact of killing Emperor Yi;" },
  { zh: "於人之功無所記，於人之罪無所忘；", literal: "for others’ merit he records nothing, and for others’ faults he forgets nothing;", idiomatic: "he records no merit and forgets no fault;" },
  { zh: "戰勝而不得其賞，拔城而不得其封，非項氏莫得用事；", literal: "those who win battles receive no reward, those who take cities receive no enfeoffment—none but the Xiang clan may hold office;", idiomatic: "victors receive no reward, conquerors receive no fief—none but the Xiang clan may hold office;" },
  { zh: "天下畔之，賢才怨之，而莫為之用。", literal: "All under Heaven turns from him, worthy talents resent him, and none will serve him.", idiomatic: "the realm turns from him, worthy talents resent him, and none will serve him." },
  { zh: "故天下之事歸於漢王，可坐而策也！", literal: "Therefore the affairs of All under Heaven turn to the King of Han—one may sit and reckon it!", idiomatic: "Therefore the realm’s affairs turn to the King of Han—you may sit and reckon it!”" },
  { zh: "夫漢王發蜀、漢，定三秦；", literal: "The King of Han raised Shu and Han, settled the Three Qin;", idiomatic: "The King of Han raised Shu and Han and settled the Three Qin;" },
  { zh: "涉西河，破北魏；", literal: "crossed the Western River and broke Northern Wei;", idiomatic: "crossed the Western River and broke Northern Wei;" },
  { zh: "出井陘，誅成安君；", literal: "went out through Jingxing and executed Lord Cheng’an;", idiomatic: "went out through Jingxing and executed Lord Cheng’an;" },
  { zh: "此非人之力也，天之福也！", literal: "this is not human strength—it is Heaven’s blessing!", idiomatic: "this is not human strength—it is Heaven’s blessing!”" },
  { zh: "今已據敖倉之粟，塞成皋之險，守白馬之津，杜太行之阪，距蜚狐之口；", literal: "Now he already holds Aocang’s grain, blocks Chenggao’s passes, guards the White Horse Ford, shuts Taihang’s slopes, and holds Feihu’s mouth;", idiomatic: "Now he holds Aocang’s grain, blocks Chenggao’s passes, guards the White Horse Ford, shuts Taihang’s slopes, and holds Feihu’s mouth;" },
  { zh: "天下後服者先亡矣。", literal: "those under Heaven who submit late will perish first.", idiomatic: "those who submit late will perish first.”" },
  { zh: "王疾先下漢王，齊國可得而保也；", literal: "If the king hastens to submit first to the King of Han, the state of Qi may be preserved;", idiomatic: "If Your Majesty hastens to submit first to the King of Han, Qi may be preserved;" },
  { zh: "不然，危亡可立而待也！", literal: "if not, peril and ruin may be awaited standing!", idiomatic: "if not, ruin may come in an instant!”" },
  { zh: "」先是，齊聞韓信且東兵，使華無傷、田解將重兵屯歷下以距漢。", literal: "” Earlier, Qi, hearing that Han Xin was about to march east with troops, sent Hua Wushang and Tian Jie to command a heavy force encamped at Lixia to resist Han.", idiomatic: "” Earlier, hearing that Han Xin was about to march east, Qi sent Hua Wushang and Tian Jie with a heavy force to hold Lixia against Han." },
  { zh: "及納酈生之言，遣使與漢平，乃罷歷下守戰備，與酈生日縱酒為樂。", literal: "When he accepted Li Yiji’s words, he sent an envoy to make peace with Han, dismissed the guards and war preparations at Lixia, and daily feasted and drank with Li Yiji for pleasure.", idiomatic: "When he accepted Li Yiji’s counsel, he sent an envoy to make peace with Han, dismissed Lixia’s guards and war preparations, and daily feasted and drank with Li Yiji." },
  { zh: "韓信引兵東，未度平原，聞酈食其已說下齊，欲止。", literal: "Han Xin led his troops east; before crossing Pingyuan he heard that Li Yiji had already persuaded Qi to submit and wished to halt.", idiomatic: "Han Xin led his troops east; before crossing Pingyuan he heard that Li Yiji had already persuaded Qi to submit and wished to halt." },
  { zh: "辨士蒯徹說信曰：「將軍受詔擊齊，而漢獨發間使下齊，寧有詔止將軍乎？", literal: "The persuader Kuai Che said to Xin, “The general received orders to attack Qi, yet Han alone sent secret envoys to bring Qi to surrender—is there any edict ordering the general to halt?", idiomatic: "The persuader Kuai Che said to Xin, “You were ordered to attack Qi, yet Han alone sent secret envoys to win Qi over—was there any edict telling you to stop?" },
  { zh: "何以得毋行也？", literal: "How can you be kept from marching?", idiomatic: "How can you be held back from advancing?" },
  { zh: "且酈生，一士，伏軾掉三寸之舌，下齊七十餘城，將軍以數萬眾，歲餘乃下趙五十餘城。", literal: "Moreover, Lord Li was but one scholar; leaning on his carriage crossbar he wielded a three-inch tongue and brought down more than seventy cities of Qi, while the general with tens of thousands took more than a year to bring down fifty-odd cities of Zhao.", idiomatic: "Moreover, Lord Li was a single scholar; from his carriage he talked down more than seventy Qi cities, while you with tens of thousands needed more than a year for fifty-odd Zhao cities." },
  { zh: "為將數歲，反不如一豎儒之功乎？", literal: "After years as a general, are you really inferior to the achievement of one pedantic scholar?", idiomatic: "After years in command, are you really worth less than one bookish pedant?" },
  { zh: "」於是信然之，遂渡河。", literal: "” Thereupon Xin believed him and crossed the river.", idiomatic: "” Xin believed him and crossed the river." },
  { zh: "1冬，十月，信襲破齊歷下軍，遂至臨淄。", literal: "1 In winter, the tenth month, Xin surprised and broke the Qi army at Lixia and then reached Linzi.", idiomatic: "1 In winter, the tenth month, Xin surprised and routed the Qi army at Lixia and advanced to Linzi." },
  { zh: "齊王以酈生為賣己，乃烹之；", literal: "the King of Qi, thinking Lord Li had betrayed him, had him boiled alive;", idiomatic: "the King of Qi, believing Lord Li had sold him out, had him boiled alive;" },
  { zh: "引兵東走高密，使使之楚請救。", literal: "led his troops east in flight to Gaomi, and sent envoys to Chu to beg rescue.", idiomatic: "fled east to Gaomi with his army and sent envoys to Chu for aid." },
  { zh: "田橫走博陽，守相田光走城陽，將軍田既軍於膠東。", literal: "Tian Heng fled to Boyang, Chancellor Tian Guang fled to Chengyang, and General Tian Ji encamped in Jiaodong.", idiomatic: "Tian Heng fled to Boyang, Chancellor Tian Guang to Chengyang, and General Tian Ji encamped in Jiaodong." },
  { zh: "2楚大司馬咎守成皋，漢數挑戰，楚軍不出。", literal: "2 The Grand Marshal of Chu, Sima Jiu, held Chenggao; Han repeatedly offered battle, but the Chu army would not come out.", idiomatic: "2 Chu Grand Marshal Sima Jiu held Chenggao; Han repeatedly challenged him, but the Chu army would not fight." },
  { zh: "使人辱之，數日，咎怒，渡兵汜水。", literal: "Han sent men to insult him; after several days Jiu was enraged and led his troops across the Si River.", idiomatic: "Han sent men to insult him; after several days Jiu flew into a rage and crossed the Si with his army." },
  { zh: "士卒半渡，漢擊之，大破楚軍，盡得楚國金玉、貨賂，咎及司馬欣皆自剄汜水上。", literal: "When the soldiers were half across, Han struck and routed the Chu army utterly, taking all the gold, jade, and goods of Chu; Jiu and Sima Xin both cut their throats on the Si.", idiomatic: "While half his men were still crossing, Han attacked and routed the Chu army, seizing all its gold, jade, and treasure; Jiu and Sima Xin both cut their throats on the Si." },
  { zh: "漢王引兵渡河，復取成皋，軍廣武，就敖倉食。", literal: "The King of Han led his army across the river, retook Chenggao, encamped at Guangwu, and drew provisions from the Ao granary.", idiomatic: "The King of Han crossed the river, retook Chenggao, encamped at Guangwu, and fed his army from the Ao granary." },
  { zh: "項羽下梁地十餘城，聞成皋破，乃引兵還。", literal: "Xiang Yu had taken more than ten cities in Liang; hearing that Chenggao had fallen, he led his army back.", idiomatic: "Xiang Yu had overrun more than ten Liang cities; when he heard Chenggao had fallen, he marched back." },
  { zh: "漢軍方圍鍾離昧於滎陽東，聞羽至，盡走險阻。", literal: "The Han army was just then besieging Zhong Li Mo east of Xingyang; hearing that Yu had arrived, they all fled into difficult country.", idiomatic: "Han was besieging Zhong Li Mo east of Xingyang; when they heard Yu was coming, they all withdrew into the hills." },
  { zh: "羽亦軍廣武，與漢相守。", literal: "Yu also encamped at Guangwu and faced Han in stalemate.", idiomatic: "Yu also encamped at Guangwu and faced Han across the line." },
  { zh: "數月，楚軍食少。", literal: "After several months the Chu army had little food.", idiomatic: "After several months the Chu army was short of food." },
  { zh: "項王患之，乃為高祖，置太公其上，告漢王曰：「今不急下，吾烹太公！", literal: "The King of Xiang was troubled by this; he made a high scaffold, placed the Grand Duke on it, and told the King of Han, “If you do not surrender quickly now, I will boil the Grand Duke alive!", idiomatic: "The King of Xiang, distressed, built a high scaffold, put the Grand Duke on it, and told the King of Han, “Surrender at once or I boil your father alive!" },
  { zh: "」漢王曰：「吾與羽俱北面受命懷王，約為兄弟，吾翁即若翁；", literal: "” The King of Han said, “I and Yu both faced north to receive orders from King Huai and were sworn as brothers; my father is your father;", idiomatic: "” The King of Han said, “Yu and I both received King Huai's orders facing north and swore brotherhood; my father is your father;" },
  { zh: "必欲烹而翁，幸分我一杯羹！", literal: "if you insist on boiling your father, kindly share a cup of broth with me!", idiomatic: "if you must boil your father, kindly save me a cup of the broth!" },
  { zh: "」項王怒，欲殺之。", literal: "” The King of Xiang was enraged and wished to kill him.", idiomatic: "” The King of Xiang was furious and meant to kill him." },
  { zh: "項伯曰：「天下事未可知。", literal: "Xiang Bo said, “The outcome under Heaven is not yet known.", idiomatic: "Xiang Bo said, “The empire is still unsettled." },
  { zh: "且為天下者不顧家，雖殺之，無益，只益禍耳！", literal: "Moreover, one who seeks the realm does not heed family; even if you kill him, it does no good and only adds to disaster!", idiomatic: "A man who seeks the realm does not heed family; killing him helps nothing and only brings worse trouble!" },
  { zh: "」項王從之。", literal: "” The King of Xiang followed his advice.", idiomatic: "” The King of Xiang took his advice." },
  { zh: "項王謂漢王曰：「天下匈匈數歲者，徒以吾兩人耳。", literal: "The King of Xiang said to the King of Han, “The realm has been in turmoil these several years solely because of the two of us.", idiomatic: "The King of Xiang said to the King of Han, “The realm has been in turmoil these years solely because of us two." },
  { zh: "願與漢王挑戰，決雌雄，毋徒苦天下之民父子為也！", literal: "I wish to challenge the King of Han to decide victor and vanquished, and not vainly torment the fathers and sons of the realm!", idiomatic: "Let us fight a duel to settle victor and vanquished, and not torment the fathers and sons of the realm in vain!" },
  { zh: "」漢王笑謝曰；", literal: "” The King of Han smiled and declined, saying;", idiomatic: "” The King of Han smiled and declined:" },
  { zh: "「吾寧鬥智，不能鬥力！", literal: "“I would rather contend in wits than in strength!", idiomatic: "“I would rather match wits than match strength!" },
  { zh: "」項王三令壯士出挑戰，漢有善騎射者樓煩輒射殺之。", literal: "” The King of Xiang three times ordered stalwarts out to challenge; Han had skilled mounted archers of Loufan who shot them down each time.", idiomatic: "” The King of Xiang three times sent champions to challenge; Han's Loufan archers shot them down every time." },
  { zh: "項王大怒，乃自被甲持戟挑戰。", literal: "The King of Xiang was greatly enraged, donned armor himself, took a halberd, and came out to challenge.", idiomatic: "The King of Xiang was furious, donned armor, took a halberd, and came out himself." },
  { zh: "樓煩欲射之，項王瞋目叱之，樓煩目不敢視，手不敢發，遂走還入壁，不敢復出。", literal: "The Loufan archer wished to shoot him; the King of Xiang glared and shouted at him—the archer dared not look, dared not loose his bow, fled back into the rampart, and did not dare come out again.", idiomatic: "A Loufan archer aimed at him; the King of Xiang glared and roared—the man dared not look, dared not shoot, fled back behind the wall, and never came out again." },
  { zh: "漢王使人間問之，乃項王也，漢王大驚。", literal: "The King of Han sent men to inquire secretly; learning it was the King of Xiang, he was greatly startled.", idiomatic: "The King of Han sent scouts to ask; when he learned it was Xiang Yu himself, he was deeply shaken." },
  { zh: "於是項王乃即漢王，相與臨廣武間而語。", literal: "Thereupon the King of Xiang drew near the King of Han, and the two faced each other across the Guangwu ravine and spoke.", idiomatic: "Then Xiang Yu came up to the King of Han, and the two faced each other across the Guangwu ravine and talked." },
  { zh: "羽欲與漢王獨身挑戰。", literal: "Yu wished to duel the King of Han alone.", idiomatic: "Yu wanted a single combat with the King of Han." },
  { zh: "漢王數羽曰：「羽負約，王我於蜀、漢，罪一；", literal: "The King of Han counted Yu's crimes, saying, “Yu broke the covenant and made me king in Shu and Han—crime one;", idiomatic: "The King of Han listed Yu's crimes: “You broke the covenant and made me king in Shu and Han—first crime;" },
  { zh: "矯殺卿子冠軍，罪二；", literal: "you forged orders and killed the Young Lord, Champion of the Lords—crime two;", idiomatic: "you forged orders and killed the Young Lord, Champion of the Lords—second crime;" },
  { zh: "救趙不還報，而擅劫諸侯兵入關，罪三；", literal: "you rescued Zhao but did not report back, and on your own seized the allied armies to enter the passes—crime three;", idiomatic: "you saved Zhao but never reported back, and on your own seized the allied armies to enter the passes—third crime;" },
  { zh: "燒秦宮室，掘始皇帝塚，收私其財，罪四；", literal: "you burned the palaces of Qin, dug up the tomb of the First Emperor, and took his wealth for yourself—crime four;", idiomatic: "you burned Qin's palaces, opened the First Emperor's tomb, and kept his treasure—fourth crime;" },
  { zh: "殺秦降王子嬰，罪五；", literal: "you killed Zi Ying, the surrendered king of Qin—crime five;", idiomatic: "you killed Zi Ying, Qin's surrendered king—fifth crime;" },
  { zh: "詐坑秦子弟新安二十萬，罪六；", literal: "you treacherously buried alive two hundred thousand Qin youths at Xin'an—crime six;", idiomatic: "you treacherously buried two hundred thousand Qin youths alive at Xin'an—sixth crime;" },
  { zh: "王諸將善地而徙逐故主，罪七；", literal: "you enfeoffed your generals in good lands while displacing and driving off their former lords—crime seven;", idiomatic: "you gave your generals the best lands while driving out their former lords—seventh crime;" },
  { zh: "出逐義帝彭城，自都之，奪韓王地，並王梁、楚，多自與，罪八；", literal: "you drove out the Emperor Yi from Pengcheng and made it your own capital, seized the King of Han's territory, and united Liang and Chu under yourself, keeping much for yourself—crime eight;", idiomatic: "you drove Emperor Yi from Pengcheng and made it your capital, seized the King of Han's lands, united Liang and Chu under yourself, and kept the lion's share—eighth crime;" },
  { zh: "使人陰殺義帝江南，罪九；", literal: "you sent men to assassinate the Emperor Yi secretly south of the Yangtze—crime nine;", idiomatic: "you had Emperor Yi murdered secretly south of the Yangtze—ninth crime;" },
  { zh: "為政不平，王約不信，天下所不容，大逆無道，罪十也。", literal: "your rule is unjust, your covenants with kings are untrustworthy, the realm cannot bear you—great rebellion and utter depravity, crime ten.", idiomatic: "your rule is unjust, your royal covenants worthless, the realm cannot tolerate you—great rebellion and utter depravity, the tenth crime." },
  { zh: "吾以義兵從諸侯誅殘賊，使刑餘罪人擊公，何苦乃與公挑戰！", literal: "I lead the righteous army with the allies to punish this brutal rebel and would send a mutilated convict to strike you—why must I trouble to duel you!", idiomatic: "I lead the righteous allies to punish this brutal rebel and would send a mutilated convict to fight you—why should I bother to duel you!" },
  { zh: "」羽大怒，伏弩射中漢王。", literal: "” Yu was greatly enraged; a hidden crossbow bolt struck the King of Han.", idiomatic: "” Yu was furious; a hidden crossbow bolt hit the King of Han." },
  { zh: "漢王傷胸，乃捫足曰：「虜中吾指。", literal: "The King of Han was wounded in the chest; he then felt his foot and said, “The barbarian hit my toe.", idiomatic: "The King of Han was wounded in the chest; he felt his foot and said, “The barbarian hit my toe." },
  { zh: "」漢王病創臥，張良強請漢王起行勞軍，以安士卒，毋令楚乘勝。", literal: "” The King of Han, ill from his wound, lay abed; Zhang Liang strongly urged him to rise, go out, and comfort the army so the troops would be reassured and Chu might not profit by victory.", idiomatic: "” Bedridden from the wound, he was urged by Zhang Liang to rise, review the troops, and steady the army so Chu could not exploit a victory." },
  { zh: "漢王出行軍，疾甚，因馳入成皋。", literal: "The King of Han went out to review the army; his illness was severe, and he galloped into Chenggao.", idiomatic: "He went out to review the army, but grew much worse and galloped into Chenggao." },
  { zh: "3韓信已定臨淄，遂東追齊王。", literal: "3 Han Xin had already settled Linzi and then pursued the King of Qi eastward.", idiomatic: "3 Han Xin had secured Linzi and marched east in pursuit of the King of Qi." },
  { zh: "項王使龍且將兵，號二十萬，以救齊，與齊王合軍高密。", literal: "The King of Xiang sent Long Ju to command troops, claiming two hundred thousand, to rescue Qi; he joined the King of Qi at Gaomi.", idiomatic: "The King of Xiang sent Long Ju with an army said to number two hundred thousand to rescue Qi; he joined the King of Qi at Gaomi." },
  { zh: "客或說龍且曰：「漢兵遠鬥窮戰，其鋒不可當。", literal: "A guest urged Long Ju, saying, “The Han army has fought far from home to the point of exhaustion; its edge cannot be withstood.", idiomatic: "Someone urged Long Ju, “Han has fought far from home to exhaustion; its edge cannot be faced." },
  { zh: "齊、楚自居其地，兵易敗散。", literal: "Qi and Chu on their own ground—troops are easily defeated and scattered.", idiomatic: "Qi and Chu on home ground are easily beaten and scattered." },
  { zh: "不如深壁，令齊王使其信臣招所亡城；", literal: "Better to hold deep behind walls and have the King of Qi send trusted ministers to summon the lost cities;", idiomatic: "Better to hold behind strong walls and have the King of Qi send trusted men to win back the lost cities;" },
  { zh: "亡城聞王在，楚來救，必反漢。", literal: "when lost cities hear the king is alive and Chu comes to rescue, they will surely turn against Han.", idiomatic: "lost cities hearing their king lives and Chu is coming will surely turn on Han." },
  { zh: "漢兵二千里客居齊地，齊城皆反之，其勢無所得食，可無戰而降也。", literal: "The Han army, guests two thousand li deep in Qi, with Qi cities all turning—such a force cannot get food and can be made to surrender without fighting.", idiomatic: "Han, two thousand li from home in Qi with every city turning, will get no food and can be starved into surrender without a battle." },
  { zh: "」龍且曰：「吾平生知韓信為人，易與耳！", literal: "” Long Ju said, “All my life I have known what sort of man Han Xin is—he is easy to deal with!", idiomatic: "” Long Ju said, “I have known Han Xin all my life—he is easy to handle!" },
  { zh: "寄食於漂母，無資身之策；", literal: "He begged food from the washerwoman and had no plan to sustain himself;", idiomatic: "He begged food from a washerwoman and had no way to keep himself;" },
  { zh: "受辱於胯下，無兼人之勇，不足畏也。", literal: "he suffered humiliation under another's crotch and lacks the courage to face a foe—he is not worth fearing.", idiomatic: "he crawled under another's legs and lacks the courage to face a man—he is nothing to fear." },
  { zh: "且夫救齊，不戰而降之，吾何功！", literal: "Moreover, in rescuing Qi, if I take him without fighting, what merit is mine!", idiomatic: "Besides, if I rescue Qi without fighting and he surrenders, what credit is mine!" },
  { zh: "今戰而勝之，齊之半可得也。", literal: "If I fight now and defeat him, I can gain half of Qi.", idiomatic: "Fight and win now, and I can take half of Qi." },
  { zh: "十一月，齊、楚與漢夾濰水而陳。", literal: "In the eleventh month Qi, Chu, and Han drew up on opposite banks of the Wei River.", idiomatic: "In the eleventh month Qi, Chu, and Han faced each other across the Wei River." },
  { zh: "韓信儲夜令人為萬餘囊，滿盛沙，壅水上流；", literal: "Han Xin prepared overnight to have more than ten thousand sacks made, filled with sand, and blocked the upper stream;", idiomatic: "Han Xin had more than ten thousand sand-filled sacks made overnight and dammed the upper stream;" },
  { zh: "引軍半渡擊龍且，佯不勝，還走。", literal: "he led his army halfway across to strike Long Ju, feigned defeat, and retreated.", idiomatic: "he led his men halfway across to strike Long Ju, feigned defeat, and fell back." },
  { zh: "龍且果喜曰：「固知信怯也！", literal: "Long Ju was indeed pleased and said, “I always knew Xin was cowardly!", idiomatic: "Long Ju was delighted and said, “I always knew Xin was a coward!" },
  { zh: "」遂追信。", literal: "” He then pursued Xin.", idiomatic: "” He pursued Xin." },
  { zh: "信使人決壅囊，水大至，龍且軍太半不得渡。", literal: "Xin had men break the dammed sacks; the water rose greatly, and more than half of Long Ju's army could not cross.", idiomatic: "Xin had the dam broken; the flood surged, and more than half Long Ju's army could not cross." },
  { zh: "即急擊殺龍且，水東軍散走，齊王廣亡去。", literal: "He at once pressed the attack and killed Long Ju; the army east of the water scattered and fled, and the King of Qi, Guang, escaped.", idiomatic: "He pressed the attack at once and killed Long Ju; the army east of the river scattered, and King Guang of Qi fled." },
  { zh: "信遂追北至成陽，虜齊王廣。", literal: "Xin pursued north to Chengyang and captured the King of Qi, Guang.", idiomatic: "Xin pursued north to Chengyang and captured King Guang of Qi." },
  { zh: "漢將灌嬰追得齊守相田光，進至博陽。", literal: "The Han general Guan Ying pursued and captured Qi Chancellor Tian Guang and advanced to Boyang.", idiomatic: "Han general Guan Ying captured Qi Chancellor Tian Guang and advanced to Boyang." },
  { zh: "田橫聞齊王死，自立為齊王，還擊嬰，嬰敗橫軍於嬴下。", literal: "Tian Heng, hearing the King of Qi was dead, made himself King of Qi, turned back to strike Ying, and Ying defeated Heng's army below Ying.", idiomatic: "Tian Heng, hearing the king was dead, made himself King of Qi, turned on Ying, and Ying defeated him below Ying." },
  { zh: "田橫亡走梁，歸彭越。", literal: "Tian Heng fled to Liang and joined Peng Yue.", idiomatic: "Tian Heng fled to Liang and joined Peng Yue." },
  { zh: "嬰進擊齊將田吸於千乘，曹參擊田既於膠東，皆殺之，盡定齊地。", literal: "Ying advanced to strike the Qi general Tian Xi at Qiansheng; Cao Shen struck Tian Ji in Jiaodong; both were killed and Qi territory was wholly settled.", idiomatic: "Ying attacked Qi general Tian Xi at Qiansheng; Cao Shen attacked Tian Ji in Jiaodong; both were killed and Qi was fully pacified." },
  { zh: "4立張耳為趙王。", literal: "4 Zhang Er was established as King of Zhao.", idiomatic: "4 Zhang Er was made King of Zhao." },
  { zh: "5漢王疾愈，西入關。", literal: "5 When the King of Han's illness had healed, he entered the passes westward.", idiomatic: "5 When the King of Han recovered, he went west into the passes." },
  { zh: "至櫟陽，梟故塞王欣頭櫟陽市。", literal: "Reaching Liyang, he exposed the head of the former King of Sai, Sima Xin, in the Liyang market.", idiomatic: "At Liyang he exposed the head of the former King of Sai, Sima Xin, in the market." },
  { zh: "留四日，復如軍，軍廣武。", literal: "He stayed four days, then returned to the army and encamped at Guangwu.", idiomatic: "After four days he returned to the army and encamped at Guangwu." },
  { zh: "6韓信使人言漢王曰：「齊偽詐多變，反覆之國也；", literal: "6 Han Xin sent men to tell the King of Han, “Qi is false, treacherous, and changeable—a state that turns back on itself;", idiomatic: "6 Han Xin sent word to the King of Han, “Qi is treacherous and changeable, a state that turns on itself;" },
  { zh: "南邊楚。", literal: "on the south it borders Chu.", idiomatic: "and on the south it borders Chu." },
  { zh: "請為假王以鎮之。", literal: "I ask to be made acting king to hold it in check.", idiomatic: "I ask to be made acting king to hold it firm." },
  { zh: "」漢王發書，大怒，罵曰：「吾困於此，旦暮望若來佐我，乃欲自立為王！", literal: "” The King of Han, on opening the letter, was greatly enraged and cursed, saying, “I am trapped here and morning and evening look for you to come aid me—and you wish to make yourself king!", idiomatic: "” The King of Han opened the letter, flew into a rage, and cursed, “I am trapped here and look to you morning and night for help—and you want to make yourself king!" },
  { zh: "」張良、陳平躡漢王足，因附耳語曰：「漢方不利，寧能禁信之自王乎！", literal: "” Zhang Liang and Chen Ping trod on the King of Han's foot and whispered in his ear, “Han is at a disadvantage—can you forbid Xin from making himself king!", idiomatic: "” Zhang Liang and Chen Ping trod on his foot and whispered, “Han is losing ground—can you stop Xin from making himself king?" },
  { zh: "不如因而立之，善遇，使自為守。", literal: "Better to establish him accordingly, treat him well, and let him hold the line on his own.", idiomatic: "Better crown him now, treat him well, and let him hold the frontier himself." },
  { zh: "不然，變生。", literal: "Otherwise trouble will arise.", idiomatic: "Otherwise he will turn." },
  { zh: "」漢王亦悟，因復罵曰：「大丈夫定諸侯，即為真王耳，何以假為！", literal: "” The King of Han also understood and cursed again, saying, “When a great man settles the lords, he is a true king—why act as king in name only!", idiomatic: "” The king saw the point and cursed again, “A man who settles the lords is a true king—why only acting king!" },
  { zh: "」春，二月，遣張良操印立韓信為齊王，征其兵擊楚。", literal: "” In spring, the second month, he sent Zhang Liang with the seal to establish Han Xin as King of Qi and summon his troops to strike Chu.", idiomatic: "” In spring, the second month, he sent Zhang Liang with the seal to make Han Xin King of Qi and call up his army against Chu." },
  { zh: "----7項王聞龍且死，大懼，使盱台人涉往說齊王信曰：「天下共苦秦久矣，相與戮力擊秦。", literal: "----7 The King of Xiang, hearing Long Ju was dead, was greatly afraid and sent She of Xutai to persuade the King of Qi, Xin, saying, “All under Heaven have long suffered under Qin and joined forces to strike Qin.", idiomatic: "----7 The King of Xiang, hearing Long Ju was dead, was terrified and sent She of Xutai to King Xin of Qi, saying, “The world long suffered under Qin and joined to destroy Qin." },
  { zh: "秦已破，計功割地，分土而王之，以休士卒。", literal: "Qin was broken; merit was counted, lands divided, and men made kings to rest the armies.", idiomatic: "Qin fell; merit was counted, lands divided, kings made, and the armies rested." },
  { zh: "今漢王復興兵而東，侵人之分，奪人之地；", literal: "Now the King of Han has again raised his army and gone east, encroaching on others' shares and seizing others' lands;", idiomatic: "Now the King of Han has raised his army again and marched east, encroaching on others' shares and seizing their lands;" },
  { zh: "已破三秦，引兵出關，收諸侯之兵以東擊楚，其意非盡吞天下者不休，其不知厭足如是甚也！", literal: "having already broken the Three Qin, he leads his army out of the passes, gathers the allied armies, and strikes Chu eastward—his intent is not to rest until he has swallowed the realm whole; his knowing no sufficiency is extreme indeed!", idiomatic: "having crushed the Three Qin, he leads his army out of the passes, gathers the allied hosts, and strikes Chu eastward—he will not rest until he has swallowed the whole realm; his greed knows no limit!" },
  { zh: "且漢王不可必，身居項王掌握中數矣，項王憐而活之；", literal: "Moreover, the King of Han cannot be trusted; several times he was in the King of Xiang's grasp, and the King of Xiang pitied him and let him live;", idiomatic: "Moreover the King of Han cannot be trusted; several times he was in the King of Xiang's hands, and the king spared him;" },
  { zh: "然得脫，輒倍約，復擊項王，其不可親信如此。", literal: "yet once he escaped he at once broke the covenant and again struck the King of Xiang—he is so untrustworthy.", idiomatic: "yet once free he broke every covenant and attacked again—so untrustworthy is he." },
  { zh: "今足下雖自以與漢王為厚交，為之盡力用兵，必終為所禽矣。", literal: "Now though you take yourself to be the King of Han's close friend and exert your strength in war for him, in the end you will surely be captured by him.", idiomatic: "Though you count yourself the King of Han's close friend and spend your strength for him, in the end he will surely take you." },
  { zh: "足下所以得須臾至今者，以項王尚存也。", literal: "The reason you have lasted until now is that the King of Xiang still lives.", idiomatic: "You have lasted until now only because the King of Xiang still lives." },
  { zh: "當今二王之事，權在足下，足下右投則漢王勝，左投則項王勝。", literal: "In the contest of the two kings today, the power is in your hands—if you cast right the King of Han wins, if you cast left the King of Xiang wins.", idiomatic: "Today's contest between the two kings turns on you—tip right and Han wins, tip left and Xiang wins." },
  { zh: "項王今日亡，則次取足下。", literal: "If the King of Xiang perishes today, next he will take you.", idiomatic: "When Xiang falls, you are next." },
  { zh: "足下與項王有故，何不反漢與楚連和，參分天下王之！", literal: "You and the King of Xiang have old ties—why not turn against Han, join Chu in alliance, and divide the realm three ways as kings!", idiomatic: "You and Xiang Yu have old ties—why not turn on Han, ally with Chu, and divide the realm three ways as kings!" },
  { zh: "今釋此時而自必於漢以擊楚，且為智者固若此乎？", literal: "To abandon this moment and insist on trusting Han to strike Chu—is that how the wise surely act?", idiomatic: "To throw away this moment and trust Han to crush Chu—is that what the wise do?" },
  { zh: "」韓信謝曰：「臣事項王，官不過郎中，位不過執戟；", literal: "” Han Xin declined, saying, “Your servant served the King of Xiang; his office was no higher than gentleman of the palace, his rank no higher than halberd-bearer;", idiomatic: "” Han Xin declined: “I served the King of Xiang; my office was no higher than palace attendant, my rank no higher than halberd-bearer;" },
  { zh: "言不聽，畫不用，故倍楚而歸漢。", literal: "my words were not heeded, my plans not used—therefore I turned against Chu and returned to Han.", idiomatic: "my counsel was ignored, my plans unused—so I left Chu for Han." },
  { zh: "漢王授我上將軍印，予我數萬眾，解衣衣我，推食食我，言聽計用，故吾得以至於此。", literal: "The King of Han gave me the seal of Grand General, granted me tens of thousands of troops, removed his coat to clothe me, pushed forward his food to feed me, heeded my words and used my plans—therefore I have been able to reach this point.", idiomatic: "The King of Han gave me the Grand General's seal and tens of thousands of troops, shared his coat and his food with me, heeded my counsel and used my plans—that is how I reached where I am." },
  { zh: "夫人深親我，我倍之不祥；", literal: "The lady has shown me deep favor; for me to turn against her is inauspicious;", idiomatic: "You have shown me deep favor; to betray you would be ill-omened;" },
  { zh: "雖死不易！", literal: "even in death I will not change!", idiomatic: "I would not change even unto death!" },
  { zh: "幸為信謝項王！", literal: "kindly convey Xin's thanks to the King of Xiang!", idiomatic: "please convey my thanks to the King of Xiang!" },
  { zh: "武涉已去，蒯徹知天下權在信，乃以相人之術說信曰：「僕相君之面，不過封侯，又危不安；", literal: "After Wu She had gone, Kuai Che, knowing that the power under Heaven rested with Xin, thereupon used physiognomy to persuade Xin, saying, “Your servant reading your face—you would attain no more than a marquisate, and again be in peril and unrest;", idiomatic: "After Wu She had left, Kuai Che, knowing the balance of power under Heaven rested with Xin, used face-reading to persuade him: “Reading your face, you would rise no higher than marquis, and live in peril and unrest;" },
  { zh: "相君之背，貴乃不可言。", literal: "reading your back—your nobility is beyond words.", idiomatic: "reading your back—your eminence is beyond words.”" },
  { zh: "」韓信曰：「何謂也？", literal: "” Han Xin said, “What do you mean?", idiomatic: "” Han Xin said, “What do you mean?”" },
  { zh: "」蒯徹曰：「天下初發難也，憂在亡秦而已。", literal: "” Kuai Che said, “When the realm first rose in rebellion, the worry was only to destroy Qin.", idiomatic: "” Kuai Che said, “When the realm first rose in arms, the only worry was destroying Qin." },
  { zh: "今楚、漢分爭，使天下之人肝膽塗地，父子暴骸骨於中野，不可勝數。", literal: "Now Chu and Han contend in division, making the people of the realm smear liver and gall on the ground, fathers and sons exposing their bones in the open wild—beyond counting.", idiomatic: "Now Chu and Han fight for mastery, and the people smear their guts on the ground; fathers and sons lie unburied in the wilds beyond counting." },
  { zh: "楚人起彭城，轉鬥逐北，乘利席捲，威震天下；", literal: "The men of Chu rose from Pengcheng, turned to battle and pursued north, riding advantage to sweep all before them, their might shaking the realm;", idiomatic: "Chu rose from Pengcheng, turned and fought north in pursuit, swept all before them on the tide of victory, and shook the realm;" },
  { zh: "然兵困於京、索之間，迫西山而不能進者，三年於此矣。", literal: "yet their troops have been trapped between Jing and Suo, pressed against the western hills and unable to advance—three years have passed in this.", idiomatic: "yet for three years their army has been stuck between Jing and Suo, pinned against the western hills and unable to advance." },
  { zh: "漢王將數十萬之眾，距鞏、雒，阻山河之險，一日數戰，無尺寸之功，折北不救。", literal: "The King of Han commands several hundred thousand men, holds Gong and Luo, blocks the peril of mountains and rivers, fights several times a day, yet gains not an inch of merit—defeated in the north with no rescue.", idiomatic: "The King of Han holds several hundred thousand men at Gong and Luo behind mountains and rivers, fights several times a day, wins not an inch, and is beaten in the north with no help coming." },
  { zh: "此所謂智勇俱困者也。", literal: "This is what is called both wisdom and courage exhausted.", idiomatic: "This is what people call both wits and courage spent." },
  { zh: "百姓罷極怨望，無所歸倚。", literal: "The common people are worn to the limit, full of resentment and longing, with nowhere to lean.", idiomatic: "The people are worn out, bitter and adrift, with nowhere to turn." },
  { zh: "以臣料之，其勢非天下之賢聖固不能息天下之禍。", literal: "By your servant's reckoning, in this situation unless a sage of the realm appears, the calamity of the realm cannot be stilled.", idiomatic: "In my view, unless a sage of the realm appears, this calamity cannot end." },
  { zh: "當今兩主之命，縣於足下，足下為漢則漢勝，與楚則楚勝。", literal: "Today the fate of the two lords hangs on you; if you side with Han, Han wins; if you join Chu, Chu wins.", idiomatic: "Today the fate of both kings hangs on you—side with Han and Han wins, side with Chu and Chu wins." },
  { zh: "誠能聽臣之計，莫若兩利而俱存之，參分天下，鼎足而居，其勢莫敢先動。", literal: "If you can truly heed your servant's plan, nothing is better than both profiting and both surviving—divide the realm three ways and dwell as a tripod; in such a posture none will dare move first.", idiomatic: "If you will hear my plan, let both profit and both survive—divide the realm three ways and stand as a tripod; then none will dare strike first." },
  { zh: "夫以足下之賢聖，有甲兵之聚，據強齊，從趙、燕，出空虛之地而制其後，因民之欲，西鄉為百姓請命，則天下風走而響應矣，孰敢不聽！", literal: "With your worth and sagacity, amassed armor and troops, holding strong Qi, following Zhao and Yan, sallying into empty lands to control their rear, riding the people's desires, turning west to plead the people's case—then the realm will run like the wind and answer like an echo; who would not heed!", idiomatic: "With your talent, your gathered armies, strong Qi in hand, Zhao and Yan at your side, striking into their empty rear, and riding the people's will westward to plead for them—the realm would run to you like wind and echo; who would not follow!" },
  { zh: "割大弱強以立諸侯，諸侯已立，天下服聽，而歸德於齊。", literal: "Carve off the great to enfeeble the strong and establish the lords; once the lords are established, the realm will obey and listen and turn its virtue toward Qi.", idiomatic: "Carve the great and weaken the strong to set up the lords; once they are enthroned, the realm will obey and turn its gratitude to Qi." },
  { zh: "案齊之故，有膠、泗之地，深拱揖讓，則天下之君王相率而朝於齊矣。", literal: "Holding to Qi's old lands, with Jiao and Si territory, deep in bowing and yielding courtesy—then the kings of the realm will lead one another to court at Qi.", idiomatic: "Hold Qi's ancient lands of Jiao and Si, bow deep in courtesy, and the kings of the realm will lead one another to court at Qi." },
  { zh: "蓋聞『天與弗取，反受其咎；", literal: "I have heard, ‘Heaven grants and you do not take—on the contrary you receive blame;", idiomatic: "I have heard, ‘What Heaven offers and you refuse, you pay for in blame;" },
  { zh: "時至不行，反受其殃』。", literal: "the moment arrives and you do not act—on the contrary you receive disaster.’", idiomatic: "when the moment comes and you do not move, you pay for in ruin.’" },
  { zh: "願足下熟慮之！", literal: "I beg you to consider this thoroughly!", idiomatic: "I beg you to weigh this carefully!”" },
  { zh: "」韓信曰：「漢王遇我甚厚，吾豈可鄉利而倍義乎！", literal: "” Han Xin said, “The King of Han has treated me very generously—how could I turn toward profit and betray righteousness!", idiomatic: "” Han Xin said, “The King of Han has treated me generously—how could I turn toward profit and betray what is right!”" },
  { zh: "」蒯生曰：「始常山王、成安君為布衣時，相與為刎頸之交；", literal: "” Kuai the scholar said, “At first the King of Changshan and the Lord of Cheng'an, when they were commoners, were sworn friends unto death;", idiomatic: "” Kuai Che said, “At first the King of Changshan and the Lord of Cheng'an, as commoners, swore friendship unto death;" },
  { zh: "後爭張黶、陳澤之事，常山王殺成安君泜水之南，頭足異處。", literal: "later they quarreled over Zhang Yi and Chen Ze; the King of Changshan killed the Lord of Cheng'an south of the Zhi River—head and feet in different places.", idiomatic: "later they quarreled over Zhang Yi and Chen Ze, and the King of Changshan killed the Lord of Cheng'an south of the Zhi—head and feet in different places." },
  { zh: "此二人相與，天下至歡也，然而卒相禽者，何也？", literal: "These two in their mutual bond were the closest joy in the realm—yet in the end they seized each other; why?", idiomatic: "These two were the closest friends under Heaven—yet in the end they destroyed each other; why?" },
  { zh: "患生於多欲而人心難測也。", literal: "Trouble arises from many desires and the human heart is hard to fathom.", idiomatic: "Trouble comes from many desires and hearts that cannot be read." },
  { zh: "今足下欲行忠信以交於漢王，必不能固於二君之相與也，而事多大於張黶、陳澤者；", literal: "Now you wish to practice loyalty and faith in befriending the King of Han—you surely cannot be firmer than the bond between those two lords, and the matters at stake are greater than Zhang Yi and Chen Ze;", idiomatic: "Now you wish to be loyal and faithful toward the King of Han—you cannot be surer than those two were, and the stakes are greater than Zhang Yi and Chen Ze;" },
  { zh: "故臣以為足下必漢王之不危己，亦誤矣！", literal: "therefore your servant believes that if you are sure the King of Han will not endanger you, you are also mistaken!", idiomatic: "so I believe that if you are sure the King of Han will not harm you, you are mistaken!”" },
  { zh: "大夫種存亡越，霸句踐，立功成名而身死亡，野獸盡而獵狗烹。", literal: "Grandee Wen Zhong preserved Yue in existence and made Gou Jian hegemon, achieved merit and fame yet died in body—the wild beasts gone, the hunting dogs are boiled.", idiomatic: "Grandee Wen Zhong saved Yue and made Gou Jian hegemon, won merit and fame yet was killed—when the game is gone, the hunting dogs are boiled." },
  { zh: "夫以交友言之，則不如張耳之與成安君者也；", literal: "Speaking of friendship, you are not the equal of Zhang Er and the Lord of Cheng'an;", idiomatic: "As friendship goes, you are no closer than Zhang Er and the Lord of Cheng'an;" },
  { zh: "以忠信言之，則不過大夫種之於句踐也，此二者足以觀矣！", literal: "speaking of loyalty and faith, you are no more than Wen Zhong to Gou Jian—these two cases are enough to judge by!", idiomatic: "as loyalty and faith go, you are no more than Wen Zhong to Gou Jian—these two cases are lesson enough!”" },
  { zh: "願足下深慮之。", literal: "I beg you to consider deeply.", idiomatic: "I beg you to think deeply." },
  { zh: "且臣聞『勇略震主者身危，功蓋天下者不賞』。", literal: "Moreover your servant has heard, ‘When courage and stratagem shake the lord, the man is in peril; when merit covers the realm, he is not rewarded.’", idiomatic: "Moreover I have heard, ‘When courage and stratagem shake the lord, the man is in peril; when merit covers the realm, he goes unrewarded.’" },
  { zh: "今足下戴震主之威，挾不賞之功，歸楚，楚人不信；", literal: "Now you wear the awe that shakes the lord and carry merit that goes unrewarded; if you return to Chu, the men of Chu will not trust you;", idiomatic: "Now you wear the awe that shakes your lord and carry unrewarded merit; return to Chu and Chu will not trust you;" },
  { zh: "歸漢，漢人震恐。", literal: "return to Han, the men of Han will tremble in fear.", idiomatic: "return to Han and Han will tremble in fear." },
  { zh: "足下欲持是安歸乎？", literal: "With this in hand, where do you intend to go in peace?", idiomatic: "Where do you mean to go in safety with that in hand?”" },
  { zh: "」韓信謝曰：「先生且休矣，吾將念。", literal: "” Han Xin declined, saying, “Sir, rest for now; I will ponder it.", idiomatic: "” Han Xin declined: “Rest for now, sir; I will think it over.”" },
  { zh: "」後數日，蒯徹復說曰：「夫聽者，事之候也；", literal: "” Several days later Kuai Che again urged, saying, “Listening is the sign of affairs;", idiomatic: "” Several days later Kuai Che urged again: “Listening is the sign of affairs;" },
  { zh: "計者，事之機也；", literal: "planning is the pivot of affairs;", idiomatic: "planning is the pivot of affairs;" },
  { zh: "聽過計失而能久安者鮮矣！", literal: "those who hear amiss, lose their plans, yet can long abide in peace are few!", idiomatic: "few who hear amiss, lose their plans, and still last long in peace!" },
  { zh: "故知者，決之斷也；", literal: "therefore the wise man is decisive in his decisions;", idiomatic: "therefore the wise decide decisively;" },
  { zh: "疑者，事之害也。", literal: "the doubter is the harm of affairs.", idiomatic: "the doubter is the ruin of affairs." },
  { zh: "審豪厘之小計，遺天下之大數，智誠知之，決弗敢行者，百事之禍也。", literal: "Scrutinizing a hair's breadth of small planning while abandoning the great reckoning of the realm—though wisdom truly knows it, if resolve dares not act, that is the calamity of a hundred affairs.", idiomatic: "To weigh a hair's breadth of small plans and miss the great reckoning of the realm—to know truly yet dare not act—that is the calamity of every undertaking." },
  { zh: "夫功者，難成而易敗；", literal: "Merit is hard to achieve and easy to lose;", idiomatic: "Merit is hard to win and easy to lose;" },
  { zh: "時者，難得而易失也；", literal: "the moment is hard to gain and easy to miss;", idiomatic: "the moment is hard to seize and easy to miss;" },
  { zh: "時乎時，不再來！", literal: "the moment, ah the moment—it does not come again!", idiomatic: "the moment—ah, the moment—does not come again!”" },
  { zh: "」韓信猶豫，不忍倍漢；", literal: "” Han Xin hesitated, unable to bear turning against Han;", idiomatic: "” Han Xin hesitated, unable to bear betraying Han;" },
  { zh: "又自以功多，漢終不奪我齊，遂謝。", literal: "and on his own reckoned that his merit was great and Han would never take Qi from him—therefore he declined.", idiomatic: "and reckoned that with his great merit Han would never take Qi from him, so he declined." },
  { zh: "蒯徹因去，佯狂為巫。", literal: "Kuai Che thereupon left and feigned madness, becoming a shaman.", idiomatic: "Kuai Che then left and feigned madness as a shaman." },
  { zh: "8秋，七月，立黥布為淮南王。", literal: "8 In autumn, the seventh month, Qing Bu was established as King of Huainan.", idiomatic: "8 In autumn, the seventh month, Qing Bu was made King of Huainan." },
  { zh: "9八月，北貉燕人來致梟騎助漢。", literal: "9 In the eighth month, men of the northern Mo from Yan came to present fierce cavalry to aid Han.", idiomatic: "9 In the eighth month, northern Mo men from Yan came with fierce cavalry to aid Han." },
  { zh: "10漢王下令：軍士不幸死者，吏為衣衾棺斂，轉送其家。", literal: "10 The King of Han issued an order: when soldiers died by misfortune, officials were to provide shrouds and coffins for burial and convey them to their families.", idiomatic: "10 The King of Han ordered that when soldiers died in service, officials were to provide shrouds and coffins and send the bodies home." },
  { zh: "四方歸心焉。", literal: "From the four quarters hearts turned toward him.", idiomatic: "Hearts throughout the realm turned toward him." },
  { zh: "11是歲，以中尉周昌為御史大夫。", literal: "11 That year Zhou Chang was made grand censor from Central Commandant.", idiomatic: "11 That year Zhou Chang was appointed grand censor from Central Commandant." },
  { zh: "昌，苛從弟也。", literal: "Chang was a cousin of Ke on the paternal side.", idiomatic: "Chang was Zhou Ke's paternal cousin." },
  { zh: "12項羽自知少助；", literal: "12 Xiang Yu knew himself to have little aid;", idiomatic: "12 Xiang Yu knew he had little help;" },
  { zh: "食盡，韓信又進兵擊楚，羽患之。", literal: "his food was exhausted, and Han Xin again advanced to strike Chu—Yu was troubled by this.", idiomatic: "his food was gone, and Han Xin again advanced against Chu—Yu was deeply troubled." },
  { zh: "漢遣侯公說羽請太公。", literal: "Han sent Lord Hou to persuade Yu to release the Grand Duke.", idiomatic: "Han sent Lord Hou to persuade Yu to release the Grand Duke." },
  { zh: "羽乃與漢約，中分天下，割洪溝以西為漢，以東為楚。", literal: "Yu then made a covenant with Han to divide the realm in half, cutting west of the Hong Canal for Han and east for Chu.", idiomatic: "Yu then made a treaty with Han to divide the realm, the Hong Canal west for Han and east for Chu." },
  { zh: "九月，楚歸太公、呂-{后}-，引兵解而東歸。", literal: "In the ninth month Chu returned the Grand Duke and Empress Lü, led his troops away from the stalemate, and marched east homeward.", idiomatic: "In the ninth month Chu returned the Grand Duke and Empress Lü, broke camp, and marched east homeward." },
  { zh: "漢王欲西歸，張良、陳平說曰：「漢有天下太半，而諸侯皆附；", literal: "The King of Han wished to return west; Zhang Liang and Chen Ping urged, saying, “Han holds more than half the realm and the lords all adhere;", idiomatic: "The King of Han meant to go west; Zhang Liang and Chen Ping urged: “Han holds more than half the realm and the lords all follow;" },
  { zh: "楚兵疲食盡，此天亡之時也。", literal: "Chu troops are weary and food is exhausted—this is the hour of Heaven's destruction.", idiomatic: "Chu is weary and out of food—this is Heaven's hour to destroy them." },
  { zh: "今釋弗擊，此所謂養虎自遺患也。", literal: "If you release them now and do not strike, this is what is called rearing a tiger and bequeathing trouble to yourself.", idiomatic: "If you let them go now and do not strike, you are rearing a tiger and bequeathing trouble to yourself.”" },
  { zh: "」漢王從之。", literal: "” The King of Han followed their advice.", idiomatic: "” The King of Han took their advice." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
